"use client";

import React, { useState, useEffect, useMemo } from "react";
import { startOfMonth, endOfMonth, startOfWeek, endOfWeek, addMonths, addDays, subDays } from "date-fns";
import { CalendarDays, Users, Phone, CheckSquare } from "lucide-react";
import { CalendarHeader } from "@/features/calendar/components/CalendarHeader";
import { CalendarSidebar } from "@/features/calendar/components/CalendarSidebar";
import { CalendarGrid } from "@/features/calendar/components/CalendarGrid";
import { EventModal } from "@/features/calendar/components/EventModal";
import { CRMMetricCard, CRMMetricsGrid, CRMPageContainer } from "@/shared/components/crm";
import { toast } from "sonner";
import { CalendarSkeleton } from "@/features/calendar/components/CalendarSkeleton";

type ViewType = "month" | "week" | "day" | "agenda";

interface Filters {
  meetings: boolean;
  calls: boolean;
  tasks: boolean;
  leaves: boolean;
}

export default function CalendarPage() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [view, setView] = useState<ViewType>("month");
  const [events, setEvents] = useState<ReturnType<typeof JSON.parse>[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedEvent, setSelectedEvent] = useState<ReturnType<typeof JSON.parse> | null>(null);
  const [filters, setFilters] = useState<Filters>({ meetings: true, calls: true, tasks: true, leaves: true });

  const fetchEvents = async () => {
    try {
      setLoading(true);
      let start: Date, end: Date;
      if (view === "month") {
        start = startOfWeek(startOfMonth(currentDate));
        end = endOfWeek(endOfMonth(currentDate));
      } else if (view === "agenda") {
        start = currentDate;
        end = addMonths(currentDate, 3);
      } else {
        start = subDays(currentDate, 7);
        end = addDays(currentDate, 30);
      }

      const res = await fetch(`/api/crm/calendar?start=${start.toISOString()}&end=${end.toISOString()}`);
      if (!res.ok) throw new Error("Failed to fetch events");
      const data = await res.json();
      setEvents(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error(err);
      toast.error("Could not load calendar events.");
      setEvents([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentDate, view]);

  const filteredEvents = useMemo(() => {
    return events.filter(e => {
      if (e.type === "MEETING" && !filters.meetings) return false;
      if ((e.type === "CALL" || e.type === "FOLLOW_UP") && !filters.calls) return false;
      if (e.type === "TASK" && !filters.tasks) return false;
      if ((e.type === "HOLIDAY" || e.type === "LEAVE" || e.type === "BIRTHDAY") && !filters.leaves) return false;
      return true;
    });
  }, [events, filters]);

  const today = new Date().toDateString();
  const summary = useMemo(() => ({
    meetings: events.filter(e => e.type === "MEETING" && new Date(e.startTime).toDateString() === today).length,
    calls: events.filter(e => (e.type === "CALL" || e.type === "FOLLOW_UP") && new Date(e.startTime).toDateString() === today).length,
    tasks: events.filter(e => e.type === "TASK" && new Date(e.startTime).toDateString() === today).length,
    total: events.length,
  }), [events, today]);

  const handleDelete = async (id: string) => {
    try {
      const res = await fetch(`/api/crm/calendar/${id}`, { method: "DELETE" });
      if (!res.ok) throw new Error();
      toast.success("Event deleted");
      setSelectedEvent(null);
      fetchEvents();
    } catch {
      toast.error("Failed to delete event.");
    }
  };

  if (loading && events.length === 0) {
    return <CalendarSkeleton />;
  }

  return (
    <CRMPageContainer className="min-h-full bg-background/50">
      {/* ── HEADER ── */}
        <CalendarHeader
          currentDate={currentDate}
          view={view}
          onViewChange={setView}
          onDateChange={setCurrentDate}
          onNewEvent={() => toast.info("Event creation coming soon!")}
        />

        {/* ── METRIC CARDS ── */}
        <div>
          <CRMMetricsGrid className="gap-3 md:gap-4">
          <CRMMetricCard
            title="Today's Meetings"
            value={summary.meetings}
            loading={loading}
            hideBottomSkeletons={true}
            icon={Users}
            color="emerald"
            trend="neutral"
            delay={0}
          />
          <CRMMetricCard
            title="Calls Today"
            value={summary.calls}
            loading={loading}
            hideBottomSkeletons={true}
            icon={Phone}
            color="orange"
            trend="neutral"
            delay={0.05}
          />
          <CRMMetricCard
            title="Tasks Due"
            value={summary.tasks}
            loading={loading}
            hideBottomSkeletons={true}
            icon={CheckSquare}
            color="indigo"
            trend="neutral"
            delay={0.1}
          />
          <CRMMetricCard
            title="Total Events"
            value={summary.total}
            loading={loading}
            hideBottomSkeletons={true}
            icon={CalendarDays}
            color="violet"
            trend="neutral"
            delay={0.15}
          />
        </CRMMetricsGrid>
        </div>

        {/* ── MAIN: Sidebar + Grid ── */}
        <div className="flex flex-col lg:flex-row gap-6 lg:gap-8 items-start">
          <CalendarSidebar
            currentDate={currentDate}
            onDateSelect={setCurrentDate}
            filters={filters}
            onFilterChange={(key, val) => setFilters(prev => ({ ...prev, [key]: val }))}
            summary={summary}
          />

          <div className="flex-1 min-w-0 w-full">
            <CalendarGrid
              events={filteredEvents}
              currentDate={currentDate}
              view={view}
              onEventClick={setSelectedEvent}
              onViewChange={(v) => setView(v)}
              onNewEvent={() => toast.info("Event creation coming soon!")}
            />
          </div>
        </div>
      <EventModal
        event={selectedEvent}
        onClose={() => setSelectedEvent(null)}
        onEdit={() => toast.info("Event edit coming soon!")}
        onDelete={handleDelete}
      />
    </CRMPageContainer>
  );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Users, UserPlus, Download, Star, CreditCard } from "lucide-react";

import dynamic from "next/dynamic";
const CustomersTable = dynamic(() => import("@/features/customers/components/CustomersTable").then(mod => ({ default: mod.CustomersTable })), {
  loading: () => <div className="h-[400px] skeleton rounded-xl" />
});
import { PageErrorState } from "@/shared/components/page-states";
import { CustomersSkeleton } from "@/features/customers/components/CustomersSkeleton";
import { useCustomers } from "@/shared/hooks/use-crm";
import { Button } from "@/shared/ui/button";
import { PageHeader } from "@/shared/components/PageHeader";
import { EmptyState } from "@/shared/components/EmptyState";
import { 
  CRMMetricCard, 
  CRMToolbar,
  CRMPageContainer,
  CRMMetricsGrid
} from "@/shared/components/crm";
import { useCRMStore } from "@/shared/store/useCRMStore";
import { toast } from "sonner";
import { FormModal } from "@/shared/components/form-modal";
const CustomerForm = dynamic(() => import("@/features/forms/CustomerForm").then(mod => ({ default: mod.CustomerForm })), {
  loading: () => <div className="h-[300px] skeleton rounded-xl" />
});
import { useSearchParams } from "next/navigation";

const CustomersGrid = dynamic(() => import("@/features/customers/components/CustomersGrid").then(mod => ({ default: mod.CustomersGrid })), {
  loading: () => <div className="h-[400px] skeleton rounded-xl" />
});
import { useViewMode } from "@/shared/hooks/useViewMode";

const CustomersPage = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [segmentFilter, setSegmentFilter] = useState("all");
  const [viewMode, setViewMode] = useViewMode("customers", "list");

  const { customers, setCustomers } = useCRMStore();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const safeCustomers = Array.isArray(customers) ? customers : [];
  const { data, isLoading: loading, error, refetch } = useCustomers();

  const searchParams = useSearchParams();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [selectedCustomer, setSelectedCustomer] = useState<any | null>(null);

  useEffect(() => {
    if (searchParams.get("new") === "true") {
      const timer = setTimeout(() => {
        setIsAddModalOpen(true);
        const newUrl = window.location.pathname;
        window.history.replaceState({}, "", newUrl);
      }, 0);
      return () => clearTimeout(timer);
    }
  }, [searchParams]);

  useEffect(() => {
    if (data?.customers) {
      setCustomers(data.customers);
    }
  }, [data?.customers, setCustomers]);

  const filteredCustomers = useMemo(() => {
    return safeCustomers.filter((customer) => {
      const normalizedQuery = searchQuery.toLowerCase();
      const matchesSearch =
        customer.name.toLowerCase().includes(normalizedQuery) ||
        customer.company.toLowerCase().includes(normalizedQuery) ||
        customer.email.toLowerCase().includes(normalizedQuery);
      
      const matchesStatus =
        statusFilter === "all" || customer.status.toLowerCase() === statusFilter.toLowerCase();
      
      const matchesSegment = 
        segmentFilter === "all" || customer.segment === segmentFilter;

      return matchesSearch && matchesStatus && matchesSegment;
    });
  }, [safeCustomers, searchQuery, statusFilter, segmentFilter]);

  const handleNewCustomer = () => {
    setIsAddModalOpen(true);
  };

  const handleExport = () => {
    toast.success("Customer Export Ready", {
      description: `Downloading relationship data for ${filteredCustomers.length} clients.`,
    });
  };

  if (loading && safeCustomers.length === 0) {
    return <CustomersSkeleton />;
  }

  if (error && safeCustomers.length === 0) {
    return (
      <PageErrorState
        title="CRM Intelligence Offline"
        message={(error as Error).message || "An error occurred"}
        onRetry={() => { refetch(); }}
      />
    );
  }

  const monthlyRevenue = safeCustomers.reduce((sum, customer) => sum + (customer.revenueValue ?? 0), 0);

  return (
    <CRMPageContainer className="min-h-full !pb-4 md:!pb-6 space-y-0 gap-4 md:gap-6 flex flex-col">
      <PageHeader 
        title="Customers"
        subtitle="Manage your client relationships and monitor account health with AI-powered analytics."
        icon={Users}
        badge="Relationship Intelligence"
        actions={[
          {
            label: "Export",
            icon: Download,
            onClick: handleExport,
            variant: "outline"
          },
          {
            label: "New Customer",
            icon: UserPlus,
            onClick: handleNewCustomer,
            variant: "default"
          }
        ]}
      />

      <div className="shrink-0">
        <CRMMetricsGrid cols={3}>
          <CRMMetricCard 
            title="Total Customers"
            value={safeCustomers.length}
            change="0%"
            trend="up"
            icon={Users}
            color="blue"
            delay={0.1}
          />
          <CRMMetricCard 
            title="VIP Clients"
            value={safeCustomers.filter(c => c.status === "PREMIUM").length}
            change="0%"
            trend="up"
            icon={Star}
            color="pink"
            delay={0.2}
          />
          <CRMMetricCard 
            title="Monthly Revenue"
            value={monthlyRevenue.toLocaleString("en-US")}
            change="0%"
            trend="up"
            icon={CreditCard}
            color="emerald"
            delay={0.3}
          />
        </CRMMetricsGrid>
      </div>

      <div className="flex-1 flex flex-col gap-4">
        <div className="shrink-0 mb-2 sticky top-0 z-40 bg-background/95 backdrop-blur-md py-4 -mx-4 px-4 sm:-mx-6 sm:px-6 lg:-mx-10 lg:px-10">
          <CRMToolbar 
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            viewMode={viewMode}
            setViewMode={setViewMode}
            placeholder="Search customers, companies..."
          >
            <div className="flex items-center gap-2">
              {["All", "Active", "Premium"].map((status) => (
                <Button
                  key={status}
                  variant={statusFilter === status.toLowerCase() ? "secondary" : "ghost"}
                  size="sm"
                  onClick={() => setStatusFilter(status.toLowerCase())}
                  className="h-8 px-3 text-xs font-semibold"
                >
                  {status}
                </Button>
              ))}
            </div>
          </CRMToolbar>
        </div>

        <div className="flex-1 min-h-0 flex flex-col">
          <AnimatePresence mode="wait">
            {filteredCustomers.length > 0 ? (
              <motion.div
                key={viewMode}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex-1 flex flex-col min-h-0"
              >
                {viewMode === "list" || viewMode === "table" ? (
                  <CustomersTable 
                    customers={filteredCustomers} 
                    onEdit={(customer) => {
                      setSelectedCustomer(customer);
                      setIsAddModalOpen(true);
                    }}
                  />
                ) : (
                  <CustomersGrid 
                    customers={filteredCustomers} 
                    onEdit={(customer) => {
                      setSelectedCustomer(customer);
                      setIsAddModalOpen(true);
                    }}
                  />
                )}
              </motion.div>
            ) : (
          <EmptyState
            icon={Users}
            title="No customers found"
            description="No customers match the current search or filters."
          />
            )}
          </AnimatePresence>
        </div>
      </div>

      <FormModal
        title={selectedCustomer ? "Edit Customer" : "Register New Customer"}
        description={selectedCustomer ? "Update client details." : "Add a new client to your CRM database."}
        isOpen={isAddModalOpen}
        onOpenChange={(open) => {
          setIsAddModalOpen(open);
          if (!open) setSelectedCustomer(null);
        }}
        size="lg"
      >
        <CustomerForm 
          initialData={selectedCustomer || undefined}
          onSuccess={() => { setIsAddModalOpen(false); setSelectedCustomer(null); }} 
          onCancel={() => { setIsAddModalOpen(false); setSelectedCustomer(null); }} 
        />
      </FormModal>
    </CRMPageContainer>
  );
};

export default CustomersPage;

"use client";

import React from "react";
import dynamic from "next/dynamic";
import { Download } from "lucide-react";
import { DashboardSkeleton } from "@/features/dashboard/components/DashboardSkeleton";
import { useDashboardInitializer } from "@/shared/hooks/use-dashboard";
import { Button } from "@/shared/ui/button";
import { CRMPageContainer } from "@/shared/components/crm";
import { useCRMStore } from "@/shared/store/useCRMStore";
import { toast } from "sonner";


// Standard dynamic imports
const RecentActivities = dynamic(() => import("@/features/dashboard/components/RecentActivities"));
const UpcomingMeetings = dynamic(() => import("@/features/dashboard/components/UpcomingMeetings"));
const HotLeads = dynamic(() => import("@/features/dashboard/components/HotLeads"));
const PendingFollowups = dynamic(() => import("@/features/dashboard/components/PendingFollowups"));
const CalendarWidget = dynamic(() => import("@/features/dashboard/components/CalendarWidget"));
import WelcomeBanner from "@/features/dashboard/components/WelcomeBanner";
import { DashboardWidgetWrapper } from "@/features/dashboard/components/DashboardWidgetWrapper";
import CreateNewMenu from "@/features/dashboard/components/CreateNewMenu";
import DashboardKPIs from "@/features/dashboard/components/DashboardKPIs";
import DashboardFilterMenu from "@/features/dashboard/components/DashboardFilterMenu";

const AIInsights = dynamic(() => import("@/features/reports/components/AIInsights"));
const RevenueTarget = dynamic(() => import("@/features/reports/components/RevenueTarget"));
const RevenueChart = dynamic(() => import("@/features/reports/components/RevenueChart"));
const SalesFunnel = dynamic(() => import("@/features/reports/components/SalesFunnel"));
const RecentCustomers = dynamic(() => import("@/features/dashboard/components/RecentCustomers"));

const DashboardPage = () => {
  const { 
    activeTimeframe, setActiveTimeframe 
  } = useCRMStore();

  const { 
    queries, 
    isAuthInitializing,
  } = useDashboardInitializer(activeTimeframe);

  if (isAuthInitializing) {
    return <DashboardSkeleton />;
  }

  const handleExport = () => {
    toast.success("Preparing PDF export...", {
      description: "Opening print dialog for dashboard...",
    });
    setTimeout(() => {
      window.print();
    }, 500);
  };

  return (
    <CRMPageContainer>
      <div className="flex flex-col gap-6">
        {/* Row 1: Hero Banner */}
        <WelcomeBanner />

        {/* Action Bar */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex flex-wrap items-center gap-2">
            {(['today', 'week', 'month', 'year'] as const).map((t) => (
              <Button
                key={t}
                variant={activeTimeframe === t ? "default" : "outline"}
                size="sm"
                onClick={() => setActiveTimeframe(t)}
                className="capitalize h-8 px-4 rounded-full text-xs font-semibold tracking-wide shadow-sm transition-all"
              >
                {t}
              </Button>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-2 sm:gap-3">
            <DashboardFilterMenu />
            <Button variant="outline" size="sm" onClick={handleExport} className="rounded-full h-9 px-3 sm:px-4 text-xs font-bold gap-2 print:hidden">
              <Download className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">Export PDF</span>
            </Button>
            <div className="hidden sm:block h-4 w-px bg-border mx-1" />
            <CreateNewMenu />
          </div>
        </div>

        {/* Row 2: KPI Grid */}
        <DashboardKPIs />


        {/* Row 4 & 5: Operational Layout */}
        <div className="grid grid-cols-1 xl:grid-cols-4 gap-6">
          <div className="xl:col-span-3 flex flex-col gap-6">
            
            <div className="grid grid-cols-1 gap-6">
              <DashboardWidgetWrapper 
                id="revenueChart" 
                title="Revenue Chart"
                isLoading={queries.analytics.isLoading}
                isError={queries.analytics.isError}
                onRetry={() => queries.analytics.refetch()}
                delay={1.2}
              >
                <div className="h-[350px]">
                  <RevenueChart 
                    data={queries.analytics.data?.revenueOverview?.map(r => ({ name: r.name, total: r.revenue })) || []} 
                  />
                </div>
              </DashboardWidgetWrapper>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <DashboardWidgetWrapper 
                id="upcomingMeetings" 
                title="Upcoming Meetings"
                isLoading={queries.meetings.isLoading}
                isError={queries.meetings.isError}
                onRetry={() => queries.meetings.refetch()}
                delay={0.7}
              >
                <UpcomingMeetings />
              </DashboardWidgetWrapper>

              <DashboardWidgetWrapper 
                id="pendingFollowups" 
                title="Pending Tasks"
                isLoading={queries.tasks.isLoading}
                isError={queries.tasks.isError}
                onRetry={() => queries.tasks.refetch()}
                delay={0.8}
              >
                <PendingFollowups />
              </DashboardWidgetWrapper>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <DashboardWidgetWrapper 
                id="hotLeads" 
                title="Hot Leads"
                isLoading={queries.hotLeads.isLoading}
                isError={queries.hotLeads.isError}
                onRetry={() => queries.hotLeads.refetch()}
                delay={0.9}
              >
                <HotLeads />
              </DashboardWidgetWrapper>

              <DashboardWidgetWrapper 
                id="recentActivities" 
                title="Recent Activities"
                isLoading={queries.dashboard.isLoading}
                isError={queries.dashboard.isError}
                onRetry={() => queries.dashboard.refetch()}
                delay={1.1}
              >
                <RecentActivities />
              </DashboardWidgetWrapper>
            </div>

            <div className="grid grid-cols-1 gap-6">
              <DashboardWidgetWrapper 
                id="recentCustomers" 
                title="Recent Customers"
                isLoading={queries.customers?.isLoading || false}
                isError={queries.customers?.isError || false}
                onRetry={() => queries.customers?.refetch()}
                delay={1.3}
              >
                <div className="h-[350px]">
                  <RecentCustomers />
                </div>
              </DashboardWidgetWrapper>
            </div>

          </div>

          {/* Right Sidebar (Sticky) */}
          <div className="flex flex-col gap-6 w-full xl:sticky xl:top-24 self-start">
            
            <DashboardWidgetWrapper 
              id="revenueTarget" 
              title="Revenue Target"
              isLoading={queries.dashboard.isLoading}
              isError={queries.dashboard.isError}
              onRetry={() => queries.dashboard.refetch()}
              delay={1.2}
            >
              <RevenueTarget data={queries.dashboard.data?.revenueTarget ?? null} />
            </DashboardWidgetWrapper>

            <AIInsights />

            <DashboardWidgetWrapper 
              id="calendarWidget" 
              title="Calendar"
              delay={1.3}
            >
              <CalendarWidget />
            </DashboardWidgetWrapper>
          </div>
        </div>

      </div>
    </CRMPageContainer>
  );
};

export default DashboardPage;

