"use client";

import { useState, useMemo, useEffect } from "react";
import { FileText, Plus, Download, TrendingUp, Clock } from "lucide-react";

import dynamic from "next/dynamic";
const QuotationsTable = dynamic(() => import("@/features/quotations/components/QuotationsTable"), {
  loading: () => <div className="h-[400px] skeleton rounded-xl" />
});
const QuotationsGrid = dynamic(() => import("@/features/quotations/components/QuotationsGrid").then(mod => ({ default: mod.QuotationsGrid })), {
  loading: () => <div className="h-[400px] skeleton rounded-xl" />
});
import { useViewMode } from "@/shared/hooks/useViewMode";
import { EmptyState } from "@/shared/components/EmptyState";
import { PageErrorState } from "@/shared/components/page-states";
import { QuotationsSkeleton } from "@/features/quotations/components/QuotationsSkeleton";
import { useQuotations } from "@/shared/hooks/use-crm";
import { Button } from "@/shared/ui/button";
import { 
  CRMPageHeader, 
  CRMMetricCard, 
  CRMToolbar,
  CRMPageContainer,
  CRMMetricsGrid
} from "@/shared/components/crm";
import { motion, AnimatePresence } from "framer-motion";
import { useCRMStore } from "@/shared/store/useCRMStore";
import { toast } from "sonner";
import { FormModal } from "@/shared/components/form-modal";
const QuoteForm = dynamic(() => import("@/features/forms/QuoteForm").then(mod => ({ default: mod.QuoteForm })), {
  loading: () => <div className="h-[300px] skeleton rounded-xl" />
});
import { useRouter, useSearchParams } from "next/navigation";
import { QuotationType } from "@/shared/types/quotation";

const QuotationsPage = () => {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [viewMode, setViewMode] = useViewMode("quotations", "list");

  const { quotations, setQuotations } = useCRMStore();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const safeQuotations = Array.isArray(quotations) ? quotations : [];
  const { data, isLoading: loading, error, refetch } = useQuotations();

  const searchParams = useSearchParams();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editQuote, setEditQuote] = useState<QuotationType | null>(null);

  useEffect(() => {
    const editId = searchParams.get("edit");
    if (editId && data?.quotations) {
      const q = data.quotations.find((q) => q.id === editId || q.quoteId === editId);
      if (q) {
        setEditQuote(q);
        setIsAddModalOpen(true);
      }
      // Remove edit param from url
      const newUrl = new URL(window.location.href);
      newUrl.searchParams.delete("edit");
      window.history.replaceState({}, "", newUrl.toString());
    }
  }, [searchParams, data?.quotations]);

  useEffect(() => {
    if (searchParams.get("new") === "true") {
      const timer = setTimeout(() => {
        setEditQuote(null);
        setIsAddModalOpen(true);
        const newUrl = window.location.pathname;
        window.history.replaceState({}, "", newUrl);
      }, 0);
      return () => clearTimeout(timer);
    }
  }, [searchParams]);

  useEffect(() => {
    if (data?.quotations) {
      setQuotations(data.quotations);
    }
  }, [data?.quotations, setQuotations]);

  const filteredQuotations = useMemo(() => {
    return safeQuotations.filter((quotation) => {
      const normalizedQuery = searchQuery.toLowerCase();
      const matchesSearch =
        quotation.quoteId.toLowerCase().includes(normalizedQuery) ||
        quotation.client.toLowerCase().includes(normalizedQuery) ||
        "System".toLowerCase().includes(normalizedQuery);
      const matchesStatus =
        statusFilter === "all" || quotation.status.toLowerCase() === statusFilter.toLowerCase();

      return matchesSearch && matchesStatus;
    });
  }, [safeQuotations, searchQuery, statusFilter]);

  const handleCreateQuote = () => {
    setEditQuote(null);
    setIsAddModalOpen(true);
  };

  const handleExport = () => {
    toast.success("Sales Analytics Ready", {
      description: `Downloading manifest for ${filteredQuotations.length} quotes.`,
    });
  };

  if (loading && safeQuotations.length === 0) {
    return <QuotationsSkeleton />;
  }

  if (error && safeQuotations.length === 0) {
    return (
      <PageErrorState
        title="Quotations unavailable"
        message={(error as Error).message || "An error occurred"}
        onRetry={() => { refetch(); }}
      />
    );
  }

  const averageDealSize = safeQuotations.length
    ? Math.round(safeQuotations.reduce((sum, quote) => sum + (quote.amountValue ?? 0), 0) / safeQuotations.length)
    : 0;

  return (
    <CRMPageContainer className="min-h-full !pb-4 md:!pb-6 space-y-0 gap-4 md:gap-6 flex flex-col">
      <CRMPageHeader 
        title="Quotations"
        subtitle="Generate and manage sales quotes with real-time tracking and AI-driven conversion probability."
        icon={FileText}
        badge="Sales Intelligence"
        actions={[
          {
            label: "Export",
            icon: Download,
            onClick: handleExport,
            variant: "outline"
          },
          {
            label: "Create Quote",
            icon: Plus,
            onClick: handleCreateQuote,
            variant: "default"
          }
        ]}
      />

      <div className="shrink-0">
        <CRMMetricsGrid cols={4} className="gap-4">
          <CRMMetricCard 
            title="Total Quotations"
            value={data?.stats?.[0]?.value || safeQuotations.length}
            change="0%"
            trend="up"
            icon={FileText}
            color="indigo"
            delay={0.1}
          />
          <CRMMetricCard 
            title="Total Quote Value"
            value={data?.stats?.[1]?.value || `$${safeQuotations.reduce((sum, q) => sum + (q.amountValue ?? 0), 0).toLocaleString("en-US")}`}
            change="0%"
            trend="up"
            icon={TrendingUp}
            color="emerald"
            delay={0.2}
          />
          <CRMMetricCard 
            title="Pending Quotes"
            value={data?.stats?.[2]?.value || safeQuotations.filter(q => q.status === "SENT").length}
            change="0%"
            trend="neutral"
            icon={Clock}
            color="orange"
            delay={0.3}
          />
          <CRMMetricCard 
            title="Approved Quotes"
            value={data?.stats?.[3]?.value || safeQuotations.filter(q => q.status === "ACCEPTED").length}
            change="0%"
            trend="up"
            icon={FileText}
            color="emerald"
            delay={0.4}
          />
        </CRMMetricsGrid>
      </div>

      <div className="flex-1 flex flex-col gap-4">
        <div className="shrink-0 mb-2 sticky top-0 z-40 bg-background/95 backdrop-blur-md py-4 -mx-4 px-4 sm:-mx-6 sm:px-6 lg:-mx-10 lg:px-10">
          <CRMToolbar 
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            viewMode={viewMode}
            setViewMode={setViewMode}
            placeholder="Search quotes, clients..."
          >
            <div className="flex items-center gap-2">
              {["All", "Draft", "Sent", "Accepted", "Rejected", "Expired"].map((status) => (
                <Button
                  key={status}
                  variant={statusFilter === status.toLowerCase() ? "secondary" : "ghost"}
                  size="sm"
                  onClick={() => setStatusFilter(status.toLowerCase())}
                  className="h-9 px-3 text-xs font-semibold"
                >
                  {status}
                </Button>
              ))}
            </div>
          </CRMToolbar>
        </div>

        <div className="flex-1 min-h-0 flex flex-col">
          <AnimatePresence mode="wait">
            {filteredQuotations.length > 0 ? (
              <motion.div
                key={viewMode}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="flex-1 flex flex-col min-h-0"
              >
                {viewMode === "list" || viewMode === "table" ? (
                  <QuotationsTable quotations={filteredQuotations} />
                ) : (
                  <QuotationsGrid quotations={filteredQuotations} />
                )}
              </motion.div>
            ) : (
              <EmptyState 
                icon={FileText}
                title="No quotations found"
                description="Create your first quotation to send a professional proposal to your customer."
              />
            )}
      </AnimatePresence>
        </div>
      </div>

      <FormModal
        title={editQuote ? "Edit Sales Quotation" : "Create Sales Quotation"}
        description={editQuote ? "Update the details of your existing quotation." : "Generate a professional quote for your client."}
        isOpen={isAddModalOpen}
        onOpenChange={setIsAddModalOpen}
        size="lg"
      >
        <QuoteForm 
          initialData={editQuote || undefined}
          onSuccess={() => setIsAddModalOpen(false)} 
          onCancel={() => setIsAddModalOpen(false)} 
        />
      </FormModal>
    </CRMPageContainer>
  );
};

export default QuotationsPage;

"use client";

import { useState } from "react";
import { BarChart3, Download, Calendar, TrendingUp, Users, DollarSign, IndianRupee, Target, RefreshCcw } from "lucide-react";
import dynamic from "next/dynamic";
import { PageErrorState } from "@/shared/components/page-states";
import { ReportsSkeleton } from "@/features/reports/components/ReportsSkeleton";
import { useReports, useEmployees } from "@/shared/hooks/use-crm";
import { useCurrency } from "@/shared/hooks/use-currency";
import { CRMPageHeader, CRMMetricCard, CRMPageContainer, CRMMetricsGrid } from "@/shared/components/crm";
import { toast } from "sonner";

const RevenueChart = dynamic(() => import("@/features/reports/components/RevenueChart"));
const ConversionChart = dynamic(() => import("@/features/reports/components/ConversionChart"));
const PerformanceTable = dynamic(() => import("@/features/reports/components/PerformanceTable"));
const AnalyticsSummary = dynamic(() => import("@/features/reports/components/AnalyticsSummary"));
const SalesFunnel = dynamic(() => import("@/features/reports/components/SalesFunnel"));
const RevenueTarget = dynamic(() => import("@/features/reports/components/RevenueTarget"));
const LeadSourceChart = dynamic(() => import("@/features/reports/components/LeadSourceChart"));
const SalesActivities = dynamic(() => import("@/features/reports/components/SalesActivities"));
const TopCustomers = dynamic(() => import("@/features/reports/components/TopCustomers"));
const RecentActivities = dynamic(() => import("@/features/reports/components/RecentActivities"));
const UpcomingFollowUps = dynamic(() => import("@/features/reports/components/UpcomingFollowUps"));
const AIInsights = dynamic(() => import("@/features/reports/components/AIInsights"));

const ReportsPage = () => {
  const [filters, setFilters] = useState<{ startDate?: string, endDate?: string, assignedToId?: string }>({});
  
  const { data, isLoading: loading, error, refetch, isFetching } = useReports(filters);
  const { data: employeesData } = useEmployees();
  
  const { currency } = useCurrency();
  const CurrencyIcon = currency === "INR" ? IndianRupee : DollarSign;

  const handleTimePeriod = () => {
    // Demo implementation for toggling this month filter
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
    
    if (filters.startDate === firstDay) {
      setFilters({});
      toast.success("Filters cleared");
    } else {
      setFilters({ ...filters, startDate: firstDay });
      toast.info("Filtered by This Month");
    }
  };

  const handleRefresh = () => {
    refetch();
    toast.success("Dashboard refreshed");
  };

  const handleDownload = () => {
    if (!data || !data.performance) {
       toast.error("No data available to export");
       return;
    }

    try {
      const headers = ["Team Member", "Deals Closed", "Revenue Value", "Conversion Rate"];
      const rows = data.performance.map(p => [
        `"${p.name}"`,
        p.dealsClosed,
        p.revenueValue,
        `"${p.conversionRate}"`
      ]);
      
      const csvContent = [
        headers.join(","),
        ...rows.map(r => r.join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.setAttribute("href", url);
      link.setAttribute("download", `CRM_Performance_Report_${new Date().toISOString().split('T')[0]}.csv`);
      link.style.visibility = "hidden";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast.success("Export Successful", {
        description: "Your team performance report has been downloaded as a CSV.",
      });
    } catch (e) {
      toast.error("Export Failed", { description: "An error occurred while generating the report." });
    }
  };

  if (loading && !data) {
    return <ReportsSkeleton />;
  }

  if (error && !data) {
    return (
      <PageErrorState
        title="Reports unavailable"
        message={(error as Error).message || "An error occurred"}
        onRetry={() => { refetch(); }}
      />
    );
  }

  return (
    <CRMPageContainer>
      <CRMPageHeader 
        title="Reports & Analytics"
        subtitle="Comprehensive breakdown of your sales performance, revenue targets, and team efficiency."
        icon={BarChart3}
        badge="Business Intelligence"
        actions={[
          {
            label: "Refresh",
            icon: RefreshCcw,
            onClick: handleRefresh,
            variant: "outline",
            // spinning if fetching
          },
          {
            label: "This Month",
            icon: Calendar,
            onClick: handleTimePeriod,
            variant: filters.startDate ? "default" : "outline"
          },
          {
            label: "Export",
            icon: Download,
            onClick: handleDownload,
            variant: "default"
          }
        ]}
      />

      <CRMMetricsGrid cols={4} className="gap-4">
        {(data?.stats ?? []).map((stat, index) => {
          const Icon = stat.title.toLowerCase().includes("revenue") || stat.title.toLowerCase().includes("size") ? CurrencyIcon :
            stat.title.toLowerCase().includes("conversion") || stat.title.toLowerCase().includes("win") ? Target :
            stat.title.toLowerCase().includes("deal") || stat.title.toLowerCase().includes("lead") ? Users :
            TrendingUp;

          // Define an array of premium colors
          const colors: ReturnType<typeof JSON.parse>[] = ["indigo", "violet", "emerald", "rose", "pink", "cyan", "amber", "blue"];
          // We can use a deterministic color based on index or title. Let's map by title or index.
          let assignedColor = stat.color || colors[index % colors.length];

          // Let's refine based on the title to have semantic colors
          const lowerTitle = stat.title.toLowerCase();
          if (lowerTitle.includes("won") || lowerTitle.includes("conversion")) assignedColor = "emerald";
          else if (lowerTitle.includes("lost")) assignedColor = "pink"; // fallback to pink/rose
          else if (lowerTitle.includes("open")) assignedColor = "cyan";
          else if (lowerTitle.includes("total")) assignedColor = "indigo";
          else if (lowerTitle.includes("avg") || lowerTitle.includes("size")) assignedColor = "violet";
          else if (lowerTitle.includes("forecast")) assignedColor = "orange";
          else if (lowerTitle.includes("revenue")) assignedColor = "blue";

          return (
            <CRMMetricCard
              key={stat.title}
              title={stat.title}
              value={stat.value}
              change={stat.change}
              trend={stat.positive ? "up" : "down"}
              icon={Icon}
              color={assignedColor}
              sparklineData={stat.sparklineData}
              delay={0.05 * (index + 1)}
            />
          );
        })}
      </CRMMetricsGrid>

      <AnalyticsSummary insights={data?.insights ?? []} />

      {/* Main Charts Row */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-5 items-start">
        <div className="xl:col-span-2 space-y-5 h-full flex flex-col">
          <div className="flex-1 min-h-[400px] flex flex-col">
             <RevenueChart data={data?.revenueChart || []} loading={isFetching} />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-5 flex-1">
             <div className="min-h-[350px] flex flex-col">
               <ConversionChart data={data?.conversionChart || []} loading={isFetching} />
             </div>
             <div className="min-h-[350px] flex flex-col">
               <SalesFunnel data={data?.funnel ?? []} />
             </div>
          </div>
        </div>
        
        <div className="space-y-5 h-full flex flex-col">
          <RevenueTarget data={data?.revenueTarget ?? null} />
          <div className="flex-1 min-h-[300px] flex flex-col">
            <LeadSourceChart data={data?.leadSources ?? []} loading={isFetching} />
          </div>
          <div className="flex-1 min-h-[300px] flex flex-col">
            <SalesActivities data={data?.salesActivities ?? []} loading={isFetching} />
          </div>
        </div>
      </div>

      {/* Secondary Row: Customers, Activities, Follow-ups, Insights */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5">
        <div className="min-h-[400px] flex flex-col h-full">
          <TopCustomers data={data?.topCustomers ?? []} loading={isFetching} />
        </div>
        <div className="min-h-[400px] flex flex-col h-full">
          <RecentActivities data={data?.recentActivities ?? []} loading={isFetching} />
        </div>
        <div className="min-h-[400px] flex flex-col h-full">
          <UpcomingFollowUps data={data?.upcomingFollowUps ?? []} loading={isFetching} />
        </div>
        <div className="min-h-[400px] flex flex-col h-full">
          <AIInsights />
        </div>
      </div>

      {/* Team Performance */}
      <div className="space-y-4 pt-4">
        <div className="flex flex-col gap-1">
          <h2 className="text-xl font-bold tracking-tight">Team Performance</h2>
          <p className="text-muted-foreground text-sm font-medium">Detailed breakdown of sales representative metrics and activity.</p>
        </div>
        
        <PerformanceTable performance={data?.performance || []} />
      </div>
    </CRMPageContainer>
  );
};

export default ReportsPage;

