"use client";

import { useState, useMemo, useEffect } from "react";
import {
  CheckSquare,
  Plus,
  Download,
  Target,
  AlertCircle,
  List,
  Kanban,
  Calendar as CalendarIcon,
  GanttChart,
  CheckCircle2,
} from "lucide-react";

import { Grid } from "lucide-react";

import dynamic from "next/dynamic";
const TasksTable = dynamic(() => import("@/features/tasks/components/TasksTable"));
const TasksGrid = dynamic(() => import("@/features/tasks/components/TasksGrid").then(mod => ({ default: mod.TasksGrid })));
const KanbanView = dynamic(() => import("@/features/tasks/components/KanbanView").then(mod => ({ default: mod.KanbanView })));
const CalendarView = dynamic(() => import("@/features/tasks/components/CalendarView").then(mod => ({ default: mod.CalendarView })));
const TimelineView = dynamic(() => import("@/features/tasks/components/TimelineView").then(mod => ({ default: mod.TimelineView })));
const TaskDetailsModal = dynamic(() => import("@/features/tasks/components/TaskDetailsModal"));
import { EmptyState } from "@/shared/components/EmptyState";
import { PageErrorState } from "@/shared/components/page-states";
import { TasksSkeleton } from "@/features/tasks/components/TasksSkeleton";
import { useTasks } from "@/shared/hooks/use-crm";
import { useViewMode } from "@/shared/hooks/useViewMode";
import { TaskType } from "@/shared/types/task";
import { Button } from "@/shared/ui/button";
import {
  CRMPageHeader,
  CRMMetricCard,
  CRMToolbar,
  CRMPageContainer,
  CRMMetricsGrid,
} from "@/shared/components/crm";
import { motion, AnimatePresence } from "framer-motion";
import { useCRMStore } from "@/shared/store/useCRMStore";
import { toast } from "sonner";
import { FormModal } from "@/shared/components/form-modal";
import { MeetingForm } from "@/features/forms/MeetingForm";
import { CreateTaskModal } from "@/features/tasks/components/CreateTaskModal";
import { EditTaskModal } from "@/features/tasks/components/EditTaskModal";
import { useSearchParams } from "next/navigation";

const VIEW_MODES = [
  { id: "list", icon: List, label: "List" },
  { id: "grid", icon: Grid, label: "Grid" },
  { id: "kanban", icon: Kanban, label: "Board" },
  { id: "calendar", icon: CalendarIcon, label: "Calendar" },
  { id: "timeline", icon: GanttChart, label: "Timeline" },
] as const;

const STATUS_FILTERS = [
  { id: "all", label: "All" },
  { id: "PENDING", label: "Pending" },
  { id: "IN_PROGRESS", label: "In Progress" },
  { id: "BLOCKED", label: "Blocked" },
  { id: "COMPLETED", label: "Completed" },
  { id: "OVERDUE", label: "Overdue" },
  { id: "CANCELLED", label: "Cancelled" },
];

const TasksPage = () => {
  const searchParams = useSearchParams();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [viewMode, setViewMode] = useViewMode("tasks", "list");
  const [selectedTask, setSelectedTask] = useState<TaskType | null>(null);
  const [meetingTask, setMeetingTask] = useState<TaskType | null>(null);
  const [taskToEdit, setTaskToEdit] = useState<TaskType | null>(null);
  const [isAddModalOpen, setIsAddModalOpen] = useState(searchParams.get("new") === "true");

  const { tasks, setTasks } = useCRMStore();
  const safeTasks = useMemo(() => (Array.isArray(tasks) ? tasks : []), [tasks]);

  const queryParams = useMemo(() => {
    const params: Record<string, string> = {};
    if (searchQuery) params.search = searchQuery;
    if (statusFilter !== "all") params.status = statusFilter;
    return params;
  }, [searchQuery, statusFilter]);

  const { data, isLoading: loading, error, refetch } = useTasks(queryParams);

  useEffect(() => {
    if (searchParams.get("new") === "true") {
      const newUrl = window.location.pathname;
      window.history.replaceState({}, "", newUrl);
    }
  }, [searchParams]);

  useEffect(() => {
    if (data?.tasks) {
      setTasks(data.tasks);
      setSelectedTask((prev) => {
        if (!prev) return null;
        return data.tasks.find((t: TaskType) => t.id === prev.id) || prev;
      });
    }
  }, [data?.tasks, setTasks]);

  const handleScheduleMeeting = (task: TaskType) => {
    if (!task.relatedLead && !task.relatedCustomer && !task.relatedQuotation) {
      toast.error("This task is not linked to a Lead, Customer, or Deal. Link a CRM record before scheduling a meeting.");
      return;
    }
    setMeetingTask(task);
  };

  const filteredTasks = useMemo(() => {
    return safeTasks.filter((task: TaskType) => {
      const normalizedQuery = searchQuery.toLowerCase();
      const matchesSearch =
        !searchQuery ||
        task.title.toLowerCase().includes(normalizedQuery) ||
        (task.description && task.description.toLowerCase().includes(normalizedQuery)) ||
        (task.tags && task.tags.some((t) => t.toLowerCase().includes(normalizedQuery))) ||
        (task.assignedTo?.name && task.assignedTo.name.toLowerCase().includes(normalizedQuery));

      const matchesStatus = statusFilter === "all" || task.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [safeTasks, searchQuery, statusFilter]);

  const stats = data?.dashboardStats || {
    total: safeTasks.length,
    pending: safeTasks.filter((t) => t.status === "PENDING").length,
    inProgress: safeTasks.filter((t) => t.status === "IN_PROGRESS").length,
    completed: safeTasks.filter((t) => t.status === "COMPLETED").length,
    overdue: safeTasks.filter((t) => t.isOverdue || t.status === "OVERDUE").length,
    completionRate: safeTasks.length > 0 ? Math.round((safeTasks.filter((t) => t.status === "COMPLETED").length / safeTasks.length) * 100) : 0,
  };

  const handleNewTask = () => {
    setIsAddModalOpen(true);
  };

  const handleExport = () => {
    toast.success("Tasks Exported", {
      description: `Exported ${filteredTasks.length} tasks to CSV manifest.`,
    });
  };

  if (loading && safeTasks.length === 0) {
    return <TasksSkeleton />;
  }

  if (error && safeTasks.length === 0) {
    return (
      <PageErrorState title="Tasks unavailable" message={(error as Error).message || "An error occurred"} onRetry={() => { refetch(); }} />
    );
  }

  return (
    <CRMPageContainer className="min-h-full !pb-4 md:!pb-6 space-y-0 gap-4 md:gap-6 flex flex-col">
      {/* Page Header */}
      <CRMPageHeader
        title="Tasks"
        subtitle="Organize your workflow, track productivity, and collaborate with your team."
        icon={CheckSquare}
        badge="Productivity"
        actions={[
          { label: "Export", icon: Download, onClick: handleExport, variant: "outline" },
          { label: "New Task", icon: Plus, onClick: handleNewTask, variant: "default" },
        ]}
      />

      {/* Metric Cards */}
      <div className="shrink-0">
        <CRMMetricsGrid>
          <CRMMetricCard
            title="Total Tasks"
            value={stats.total}
            change={`${stats.completionRate}% Done`}
            trend="up"
            icon={CheckSquare}
            color="blue"
            delay={0.05}
          />
          <CRMMetricCard
            title="Completed"
            value={stats.completed}
            change={`${stats.completionRate}%`}
            trend="up"
            icon={CheckCircle2}
            color="emerald"
            delay={0.1}
          />
          <CRMMetricCard
            title="In Progress"
            value={stats.inProgress}
            change={`${stats.pending} Pending`}
            trend="up"
            icon={Target}
            color="orange"
            delay={0.15}
          />
          <CRMMetricCard
            title="Overdue"
            value={stats.overdue}
            change={stats.overdue > 0 ? "Requires Action" : "Clean"}
            trend={stats.overdue > 0 ? "down" : "up"}
            icon={AlertCircle}
            color="pink"
            delay={0.2}
          />
        </CRMMetricsGrid>
      </div>

      <div className="flex-1 flex flex-col gap-4">
        {/* Toolbar */}
        <div className="shrink-0 mb-2 sticky top-0 z-40 bg-background/95 backdrop-blur-md py-4 -mx-4 px-4 sm:-mx-6 sm:px-6 lg:-mx-10 lg:px-10">
          <CRMToolbar
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            viewMode={viewMode}
            setViewMode={setViewMode}
            viewOptions={VIEW_MODES}
            placeholder="Search tasks, assignees, tags..."
          >
            {/* Status filters */}
            <div className="flex items-center gap-1 overflow-x-auto scrollbar-hide max-w-full">
              {STATUS_FILTERS.map((s) => {
                const isActive = statusFilter === s.id;
                return (
                  <Button
                    key={s.id}
                    variant={isActive ? "secondary" : "ghost"}
                    size="sm"
                    onClick={() => setStatusFilter(s.id)}
                    className="h-9 px-3 text-xs font-semibold"
                  >
                    {s.label}
                  </Button>
                );
              })}
            </div>
          </CRMToolbar>
        </div>

        {/* Main content */}
        <div className="flex-1 min-h-0 flex flex-col">
          <AnimatePresence mode="wait">
            {filteredTasks.length > 0 ? (
              <motion.div
                key={viewMode}
                initial={{ opacity: 0, y: 4 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 0.2 }}
                className="flex-1 flex flex-col min-h-0"
              >
                {(viewMode === "list" || viewMode === "table") && (
                  <TasksTable tasks={filteredTasks} onTaskClick={setSelectedTask} onScheduleMeeting={handleScheduleMeeting} onEditTask={setTaskToEdit} />
                )}
                {(viewMode === "grid" || viewMode === "cards") && (
                  <TasksGrid tasks={filteredTasks} onTaskClick={setSelectedTask} />
                )}
                {viewMode === "kanban" && (
                  <KanbanView tasks={filteredTasks} onTaskClick={setSelectedTask} onAddTask={() => setIsAddModalOpen(true)} onScheduleMeeting={handleScheduleMeeting} onEditTask={setTaskToEdit} />
                )}
                {viewMode === "calendar" && (
                  <CalendarView tasks={filteredTasks} onTaskClick={setSelectedTask} />
                )}
                {viewMode === "timeline" && (
                  <TimelineView tasks={filteredTasks} onTaskClick={setSelectedTask} />
                )}
              </motion.div>
            ) : (
              <EmptyState
                icon={CheckSquare}
                title="No tasks found"
                description="No tasks match the current search or status filter."
                action={{
                  label: "Create Task",
                  onClick: handleNewTask,
                }}
              />
            )}
          </AnimatePresence>
        </div>
      </div>

      <TaskDetailsModal
        task={selectedTask}
        isOpen={!!selectedTask}
        onClose={() => setSelectedTask(null)}
        onScheduleMeeting={handleScheduleMeeting}
      />
      <CreateTaskModal
        isOpen={isAddModalOpen}
        onClose={() => setIsAddModalOpen(false)}
        onSuccess={() => refetch()}
      />
      <EditTaskModal
        task={taskToEdit}
        isOpen={!!taskToEdit}
        onClose={() => setTaskToEdit(null)}
        onSuccess={() => refetch()}
      />
      <FormModal
        isOpen={!!meetingTask}
        onOpenChange={(open) => !open && setMeetingTask(null)}
        title="Meeting"
      >
        <MeetingForm
          defaultTaskId={meetingTask?.id}
          defaultLeadId={meetingTask?.relatedLead?.id || undefined}
          defaultCustomerId={meetingTask?.relatedCustomer?.id || undefined}
          defaultQuotationId={meetingTask?.relatedQuotation?.id || undefined}
          onSuccess={() => {
            setMeetingTask(null);
            refetch();
          }}
          onCancel={() => setMeetingTask(null)}
        />
      </FormModal>
    </CRMPageContainer>
  );
};

export default TasksPage;

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import { verifyJWT } from "@/shared/lib/auth/jwt";
import { cookies } from "next/headers";
import { AuthService } from "@/services/auth.service";
import { extractClientIp } from "@/shared/lib/auth/utils";

 
export async function GET(req: Request) {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get("auth_token")?.value;
    const refreshToken = cookieStore.get("refresh_token")?.value;
    
    const payload = token ? await verifyJWT(token) : null;

    // If access token is missing or invalid, try to auto-refresh
    if (!payload) {
      if (!refreshToken) {
        return NextResponse.json({ success: false, data: { user: null }, error: { code: "UNAUTHORIZED", message: "Not authenticated" } }, { status: 401 });
      }

      try {
        const ip = extractClientIp(req);
        const userAgent = req.headers.get("user-agent") || undefined;
        
        const data = await AuthService.refreshSession(refreshToken, { ip, userAgent });

        const commonCookieOptions: {
          httpOnly: boolean;
          secure: boolean;
          sameSite: "lax" | "strict" | "none";
          path: string;
        } = {
          httpOnly: true,
          secure: process.env.NODE_ENV === "production",
          sameSite: "lax",
          path: "/",
        };

        cookieStore.set("auth_token", data.token, { ...commonCookieOptions, maxAge: 15 * 60 });
        
        const refreshOptions = { ...commonCookieOptions, maxAge: undefined as number | undefined };
        if (data.isExtendedSession) {
          refreshOptions.maxAge = 30 * 24 * 60 * 60; // 30 days
        }
        cookieStore.set("refresh_token", data.refreshToken, refreshOptions);

        return NextResponse.json({
          success: true,
          data: { user: data.user }
        }, { status: 200 });
      } catch (_refreshError) {
        return NextResponse.json({ success: false, data: { user: null }, error: { code: "UNAUTHORIZED", message: "Session expired" } }, { status: 401 });
      }
    }

    const user = await prisma.user.findUnique({
      where: { id: payload.userId },
      select: {
        id: true,
        name: true,
        email: true,
        status: true,
        memberships: {
          include: {
            role: {
              include: {
                permissions: true
              }
            }
          }
        }
      }
    });

    if (!user) {
      return NextResponse.json({ success: false, data: { user: null }, error: { code: "UNAUTHORIZED", message: "User not found" } }, { status: 401 });
    }

    // Format permissions and role nicely
    const membership = user.memberships[0];
    const roleName = membership?.role?.name || "EMPLOYEE";
    const permissions = membership?.role?.permissions
      .filter((rp) => rp.hasAccess)
      .map((rp) => rp.module) || [];

    return NextResponse.json({
      success: true,
      data: {
        user: {
          id: user.id,
          name: user.name,
          email: user.email,
          status: user.status,
          tenantId: payload.tenantId,
          role: roleName,
          permissions
        }
      }
    }, { status: 200 });
  } catch (error: unknown) {
    // Provide more specific error messages for database connection issues
    if (error instanceof Error && error.name.includes('Prisma')) {
      return NextResponse.json({
        success: false,
        error: { code: "DATABASE_ERROR", message: "Database connection failed. Please check your connection and try again." }
      }, { status: 503 });
    }
    
    console.error("[ME ERROR]", error);
    
    // In development mode, return the actual error message to help with debugging
    const message = process.env.NODE_ENV === "development" && error instanceof Error 
      ? error.message 
      : "An unexpected error occurred";

    return NextResponse.json({
      success: false,
      error: { code: "INTERNAL_SERVER_ERROR", message }
    }, { status: 500 });
  }
}

export async function PATCH(req: Request) {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get("auth_token")?.value;
    if (!token) return NextResponse.json({ success: false, error: { code: "UNAUTHORIZED", message: "Not authenticated" } }, { status: 401 });
    
    const payload = await verifyJWT(token);
    if (!payload) return NextResponse.json({ success: false, error: { code: "UNAUTHORIZED", message: "Invalid token" } }, { status: 401 });

    const data = await req.json();

    // Update user in DB
    const updatedUser = await prisma.user.update({
      where: { id: payload.userId },
      data: {
        name: data.name,
        email: data.email,
      }
    });

    return NextResponse.json({
      success: true,
      data: {
        user: {
          id: updatedUser.id,
          name: updatedUser.name,
          email: updatedUser.email,
          phone: (updatedUser as ReturnType<typeof JSON.parse>).phone,
          status: updatedUser.status,
          tenantId: payload.tenantId,
        }
      }
    }, { status: 200 });

  } catch (error: unknown) {
    console.error("[ME PATCH ERROR]", error);
    return NextResponse.json({ success: false, error: { code: "INTERNAL_SERVER_ERROR", message: "Failed to update profile" } }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { requireRole } from "@/lib/auth-utils";
import { handleApiError } from "@/lib/api-error";
import { RevenueService } from "@/services";
import { checkRateLimit, incrementRateLimit, getClientIp, RATE_LIMITS } from "@/lib/rate-limit";

export async function GET(request: NextRequest) {
  try {
    const session = await requireRole(["ADMIN", "MANAGER", "USER"]);
    const targets = await RevenueService.getRevenueTargets(session.tenantId);
    return NextResponse.json({ success: true, data: targets }, { status: 200 });
  } catch (error: unknown) { return handleApiError(error); }
}

export async function POST(request: NextRequest) {
  try {
    const ip = getClientIp(request);
    const identifier = `admin_${ip}`;
    const rateLimit = await checkRateLimit(identifier, RATE_LIMITS.ADMIN);
    if (!rateLimit.allowed) {
      const retryAfterSeconds = Math.ceil((rateLimit.resetTime - Date.now()) / 1000);
      return NextResponse.json(
        { success: false, error: { code: "TOO_MANY_REQUESTS", message: "Too many requests. Please try again later." } },
        { status: 429, headers: { "Retry-After": retryAfterSeconds.toString() } }
      );
    }
    await incrementRateLimit(identifier, RATE_LIMITS.ADMIN);

    const session = await requireRole(["ADMIN"]);
    const body = await request.json();
    const target = await RevenueService.createRevenueTarget(session.tenantId, body);
    return NextResponse.json({ success: true, data: target }, { status: 201 });
  } catch (error: unknown) { return handleApiError(error); }
}

