"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import type React from "react";
import { useQueryClient } from "@tanstack/react-query";
import { fetchCurrentUser, loginUser, logoutUser as clearSessionToken } from "@/shared/lib/api/auth";
import { 
  defaultRoleAccess, 
  normalizeRole, 
  type RoleAccess, 
  CRM_ROLES, 
  roleRouteConfig,
  PERMISSIONS,
} from "@/shared/lib/auth/rbac";
import { useCRMStore } from "@/shared/store/useCRMStore";

 
const _STORAGE_TOKEN_KEY = "orbit_token";
 
const _STORAGE_USER_KEY = "orbit_user";

type AuthUser = {
  id: string;
  name: string;
  email: string;
  role: string;
  roleName?: string;
  displayName?: string;
  avatar?: string;
  status?: string;
  permissions?: string[];
  routes?: string[];
  dashboardWidgets?: string[];
  analyticsVisibility?: RoleAccess["analyticsVisibility"];
  description?: string;
};

type AuthStatus = "initializing" | "authenticated" | "unauthenticated";

type AuthContextState = {
  user: AuthUser | null;
  access: RoleAccess;
  token: string | null;
  loading: boolean;
  isAuthenticated: boolean;
  isInitializing: boolean;
  isHydrated: boolean;
  login: (email: string, password: string, staySignedIn?: boolean) => Promise<void>;
  logout: () => void;
  refreshUser: () => Promise<void>;
  hasPermission: (permission: string) => boolean;
};

const AuthContext = createContext<AuthContextState | null>(null);

const WIDGETS_BY_ROLE: Record<string, string[]> = {
  [CRM_ROLES.ADMIN]: ["revenue", "newLeads", "activeDeals", "winRate", "salesChart", "upcomingMeetings", "hotLeads", "teamPerformance", "leadFunnel", "revenueTracker", "recentActivities", "pendingFollowups", "aiInsights", "calendarWidget"],
  [CRM_ROLES.MANAGER]: ["salesChart", "upcomingMeetings", "hotLeads", "teamPerformance", "leadFunnel", "recentActivities", "pendingFollowups", "calendarWidget"],
  [CRM_ROLES.SALES]: ["salesChart", "upcomingMeetings", "hotLeads", "leadFunnel", "recentActivities", "pendingFollowups", "calendarWidget"],
  [CRM_ROLES.SUPPORT]: ["upcomingMeetings", "recentActivities", "pendingFollowups", "calendarWidget"],
  [CRM_ROLES.EMPLOYEE]: ["upcomingMeetings", "recentActivities", "pendingFollowups", "calendarWidget"],
};

const PERMISSIONS_BY_ROLE: Record<string, string[]> = {
  [CRM_ROLES.ADMIN]: Object.values(PERMISSIONS),
  [CRM_ROLES.MANAGER]: [
    PERMISSIONS.DASHBOARD_VIEW,
    PERMISSIONS.LEADS_CREATE, PERMISSIONS.LEADS_READ, PERMISSIONS.LEADS_UPDATE, PERMISSIONS.LEADS_DELETE,
    PERMISSIONS.CUSTOMERS_CREATE, PERMISSIONS.CUSTOMERS_READ, PERMISSIONS.CUSTOMERS_UPDATE, PERMISSIONS.CUSTOMERS_DELETE,
    PERMISSIONS.PIPELINE_CREATE, PERMISSIONS.PIPELINE_READ, PERMISSIONS.PIPELINE_UPDATE, PERMISSIONS.PIPELINE_DELETE,
    PERMISSIONS.TASKS_CREATE, PERMISSIONS.TASKS_READ, PERMISSIONS.TASKS_UPDATE, PERMISSIONS.TASKS_DELETE,
    PERMISSIONS.QUOTATIONS_CREATE, PERMISSIONS.QUOTATIONS_READ, PERMISSIONS.QUOTATIONS_UPDATE, PERMISSIONS.QUOTATIONS_DELETE, PERMISSIONS.QUOTATIONS_APPROVE,
    PERMISSIONS.REPORTS_READ,
    PERMISSIONS.EMPLOYEES_READ, PERMISSIONS.ATTENDANCE_READ, PERMISSIONS.PERFORMANCE_READ,
    "leads.view", // Extra specific to CreateNewMenu
  ],
  [CRM_ROLES.SALES]: [
    PERMISSIONS.DASHBOARD_VIEW,
    PERMISSIONS.LEADS_CREATE, PERMISSIONS.LEADS_READ_ASSIGNED, PERMISSIONS.LEADS_UPDATE_ASSIGNED,
    PERMISSIONS.CUSTOMERS_CREATE, PERMISSIONS.CUSTOMERS_READ, PERMISSIONS.CUSTOMERS_UPDATE,
    PERMISSIONS.PIPELINE_READ, PERMISSIONS.PIPELINE_UPDATE,
    PERMISSIONS.TASKS_CREATE, PERMISSIONS.TASKS_READ_ASSIGNED, PERMISSIONS.TASKS_UPDATE_ASSIGNED,
    PERMISSIONS.QUOTATIONS_CREATE, PERMISSIONS.QUOTATIONS_READ_ASSIGNED, PERMISSIONS.QUOTATIONS_UPDATE_ASSIGNED,
    "leads.view",
  ],
  [CRM_ROLES.SUPPORT]: [
    PERMISSIONS.DASHBOARD_VIEW,
    PERMISSIONS.CUSTOMERS_READ,
    PERMISSIONS.SUPPORT_TICKETS_READ, PERMISSIONS.SUPPORT_TICKETS_MANAGE,
    PERMISSIONS.TASKS_READ_ASSIGNED, PERMISSIONS.TASKS_UPDATE_ASSIGNED,
    "leads.view",
  ],
  [CRM_ROLES.EMPLOYEE]: [
    PERMISSIONS.DASHBOARD_VIEW,
    PERMISSIONS.TASKS_READ_ASSIGNED, PERMISSIONS.TASKS_UPDATE_ASSIGNED,
    "leads.view",
  ],
};

function buildAccess(user: AuthUser | null): RoleAccess {
  if (!user) {
    return defaultRoleAccess;
  }

  const roleKey = normalizeRole(user.role);
  const allowedRoutes = roleRouteConfig[roleKey] || ["/dashboard"];

  return {
    roleName:
      user.roleName ||
      roleKey
        .split("_")
        .map((value) => value.charAt(0).toUpperCase() + value.slice(1))
        .join(" "),
    description: user.description || defaultRoleAccess.description,
    permissions: user.permissions && user.permissions.length > 0 
      ? user.permissions 
      : (PERMISSIONS_BY_ROLE[roleKey] || []),
    routes: allowedRoutes,
    dashboardWidgets: WIDGETS_BY_ROLE[roleKey] || WIDGETS_BY_ROLE[CRM_ROLES.EMPLOYEE],
    analyticsVisibility: user.analyticsVisibility || "self",
  };
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const queryClient = useQueryClient();
  const [status, setStatus] = useState<AuthStatus>("initializing");
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(false);
  const [isHydrated, setIsHydrated] = useState(false);

   
  const _isInitializing = status === "initializing";

  const logout = useCallback(async () => {
    await clearSessionToken(); // hits /api/auth/logout
    if (typeof window !== "undefined") {
      localStorage.removeItem("has_session");
    }
    setUser(null);
    setStatus("unauthenticated");
    queryClient.clear(); // Clear all cached data on logout
    useCRMStore.getState().reset(); // Reset CRM store
  }, [queryClient]);

  const refreshUser = useCallback(async () => {
    try {
      if (typeof window !== "undefined" && !localStorage.getItem("has_session")) {
        setStatus("unauthenticated");
        return;
      }
      setLoading(true);
      const currentUser = await fetchCurrentUser();
      if (!currentUser) {
        if (typeof window !== "undefined") localStorage.removeItem("has_session");
        setStatus("unauthenticated");
        return;
      }
      setUser(currentUser);
      setStatus("authenticated");
     
    } catch (_error: unknown) {
      if (typeof window !== "undefined") localStorage.removeItem("has_session");
      setStatus("unauthenticated");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    refreshUser().finally(() => setIsHydrated(true));
  }, [refreshUser]);

  useEffect(() => {
    const handleAuthExpired = () => logout();
    window.addEventListener("auth:expired", handleAuthExpired);
    return () => window.removeEventListener("auth:expired", handleAuthExpired);
  }, [logout]);

  const login = useCallback(async (email: string, password: string, staySignedIn?: boolean) => {
    try {
      setLoading(true);
      const response = await loginUser({ email, password, staySignedIn });
      
      if (typeof window !== "undefined") {
        localStorage.setItem("has_session", "1");
      }
      setUser(response.data.user);
      setStatus("authenticated");
      
      // Clear cache to ensure fresh data for the new user
      await queryClient.clear();
    } finally {
      setLoading(false);
    }
  }, [queryClient]);

  const value = useMemo<AuthContextState>(() => {
    const access = buildAccess(user);
    return {
      user,
      access,
      token: null, // Token is no longer exposed to frontend
      loading: loading || status === "initializing",
      isAuthenticated: status === "authenticated",
      isInitializing: status === "initializing",
      isHydrated,
      login,
      logout,
      refreshUser,
      hasPermission: (permission: string) => {
        if (!user) return false;
        if (user.role === CRM_ROLES.ADMIN) return true;
        return Boolean(access.permissions.includes(permission));
      },
    };
  }, [status, user, login, logout, refreshUser, loading, isHydrated]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

"use client";

import React, { useState } from "react";
import {
  format, startOfMonth, endOfMonth, startOfWeek, endOfWeek,
  addDays, isSameMonth, isSameDay, addMonths, subMonths
} from "date-fns";
import { ChevronLeft, ChevronRight, Users, Phone, CheckSquare } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { motion } from "framer-motion";

interface Filters {
  meetings: boolean;
  calls: boolean;
  tasks: boolean;
  leaves: boolean;
}

interface Summary {
  meetings: number;
  calls: number;
  tasks: number;
}

interface CalendarSidebarProps {
  currentDate: Date;
  onDateSelect: (date: Date) => void;
  filters: Filters;
  onFilterChange: (key: keyof Filters, value: boolean) => void;
  summary: Summary;
}

const filterConfig = [
  { key: "meetings" as const, label: "Meetings", dot: "bg-emerald-500" },
  { key: "calls" as const, label: "Calls & Follow-ups", dot: "bg-orange-500" },
  { key: "tasks" as const, label: "Tasks Due", dot: "bg-indigo-500" },
  { key: "leaves" as const, label: "Holidays & Leave", dot: "bg-rose-400" },
];

function MiniCalendar({ selected, onSelect }: { selected: Date; onSelect: (d: Date) => void }) {
  const [viewDate, setViewDate] = useState(new Date(selected));
  const today = new Date();

  const monthStart = startOfMonth(viewDate);
  const monthEnd = endOfMonth(viewDate);
  const gridStart = startOfWeek(monthStart, { weekStartsOn: 0 });
  const gridEnd = endOfWeek(monthEnd, { weekStartsOn: 0 });

  const rows: Date[][] = [];
  let row: Date[] = [];
  let day = gridStart;
  while (day <= gridEnd) {
    row.push(day);
    if (row.length === 7) { rows.push(row); row = []; }
    day = addDays(day, 1);
  }

  return (
    <div className="select-none">
      {/* Month nav */}
      <div className="flex items-center justify-between mb-3">
        <button
          onClick={() => setViewDate(subMonths(viewDate, 1))}
          className="w-6 h-6 rounded hover:bg-muted flex items-center justify-center text-muted-foreground hover:text-foreground transition-colors"
        >
          <ChevronLeft className="w-3.5 h-3.5" />
        </button>
        <span className="text-xs font-semibold text-foreground">
          {format(viewDate, "MMMM yyyy")}
        </span>
        <button
          onClick={() => setViewDate(addMonths(viewDate, 1))}
          className="w-6 h-6 rounded hover:bg-muted flex items-center justify-center text-muted-foreground hover:text-foreground transition-colors"
        >
          <ChevronRight className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Day-of-week headers */}
      <div className="grid grid-cols-7 mb-1">
        {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
          <div key={i} className="text-center text-[10px] font-bold text-muted-foreground/60 uppercase py-0.5">
            {d}
          </div>
        ))}
      </div>

      {/* Date grid */}
      {rows.map((week, ri) => (
        <div key={ri} className="grid grid-cols-7">
          {week.map((d, di) => {
            const isSelected = isSameDay(d, selected);
            const isToday = isSameDay(d, today);
            const inMonth = isSameMonth(d, viewDate);
            return (
              <button
                key={di}
                onClick={() => { onSelect(d); setViewDate(d); }}
                className={cn(
                  "aspect-square w-7 h-7 mx-auto flex items-center justify-center text-[11px] font-medium rounded-full transition-all",
                  isSelected
                    ? "bg-primary text-primary-foreground font-bold"
                    : isToday
                    ? "text-primary font-bold ring-1 ring-primary/30"
                    : inMonth
                    ? "text-foreground hover:bg-muted"
                    : "text-muted-foreground/30"
                )}
              >
                {format(d, "d")}
              </button>
            );
          })}
        </div>
      ))}
    </div>
  );
}

export function CalendarSidebar({ currentDate, onDateSelect, filters, onFilterChange, summary }: CalendarSidebarProps) {
  return (
    <motion.aside
      initial={{ opacity: 0, x: -16 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.3 }}
      className="hidden lg:flex w-[300px] xl:w-[320px] flex-shrink-0 flex-col bg-card rounded-xl shadow-sm border border-border/50 p-6 space-y-6 overflow-y-auto"
    >
      {/* Mini Calendar */}
      <div>
        <MiniCalendar selected={currentDate} onSelect={onDateSelect} />
      </div>

      <div className="space-y-6">
        {/* Today's Summary */}
        <div>
          <p className="text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground/60 mb-3">
            Today's Overview
          </p>
          <div className="space-y-4">
            {[
              { icon: Users, label: "Meetings", value: summary.meetings, bg: "bg-emerald-50 dark:bg-emerald-950/30", text: "text-emerald-700 dark:text-emerald-400", iconBg: "bg-emerald-100 dark:bg-emerald-900/30", iconText: "text-emerald-600 dark:text-emerald-400" },
              { icon: Phone, label: "Calls", value: summary.calls, bg: "bg-orange-50 dark:bg-orange-950/30", text: "text-orange-700 dark:text-orange-400", iconBg: "bg-orange-100 dark:bg-orange-900/30", iconText: "text-orange-600 dark:text-orange-400" },
              { icon: CheckSquare, label: "Tasks Due", value: summary.tasks, bg: "bg-indigo-50 dark:bg-indigo-950/30", text: "text-indigo-700 dark:text-indigo-400", iconBg: "bg-indigo-100 dark:bg-indigo-900/30", iconText: "text-indigo-600 dark:text-indigo-400" },
            ].map(({ icon: Icon, label, value, bg, text, iconBg, iconText }) => (
              <div key={label} className={cn("flex items-center gap-3 rounded-xl px-3 py-2 border border-transparent", bg)}>
                <div className={cn("w-6 h-6 rounded flex items-center justify-center flex-shrink-0", iconBg)}>
                  <Icon className={cn("w-3 h-3", iconText)} />
                </div>
                <span className="text-[11px] font-medium text-muted-foreground flex-1">{label}</span>
                <span className={cn("text-sm font-bold tabular-nums", text)}>{value}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Calendar Filters */}
        <div>
          <p className="text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground/60 mb-3">
            My Calendars
          </p>
          <div className="space-y-4">
            {filterConfig.map(({ key, label, dot }) => (
              <button
                key={key}
                onClick={() => onFilterChange(key, !filters[key])}
                className="flex items-center gap-3 w-full px-2 py-2 rounded-lg hover:bg-muted/60 transition-colors group"
              >
                <div className={cn(
                  "w-4 h-4 rounded border-2 flex items-center justify-center flex-shrink-0 transition-all",
                  filters[key] ? `${dot} border-transparent` : "border-muted-foreground/30 bg-transparent"
                )}>
                  {filters[key] && (
                    <svg className="w-2.5 h-2.5 text-white" viewBox="0 0 10 10" fill="none">
                      <path d="M2 5l2.5 2.5 3.5-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                  )}
                </div>
                <div className={cn("w-2 h-2 rounded-full flex-shrink-0", dot)} />
                <span className="text-xs font-medium text-muted-foreground group-hover:text-foreground transition-colors text-left">
                  {label}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </motion.aside>
  );
}

