  onCancel, 
  defaultLeadId, 
  defaultCustomerId, 
  defaultQuotationId, 
  defaultTaskId 
}: MeetingFormProps) => {
  const [activeTab, setActiveTab] = useState<"schedule" | "log">("schedule");
  const { mutate: createMeeting, isPending } = useCreateMeeting();

  const hasCrmRelation = !!(defaultLeadId || defaultCustomerId || defaultQuotationId);

  // We maintain a single form with a superset schema for UI simplicity, 
  // but use the correct resolver based on the active tab.
  const schema = activeTab === "schedule" ? scheduleMeetingSchema : logMeetingSchema;

  const form = useForm<ReturnType<typeof JSON.parse>>({
    resolver: zodResolver(schema),
    defaultValues: {
      title: "",
      time: "10:00 AM",
      notes: "",
      outcome: "",
      duration: 30,
      leadId: defaultLeadId,
      customerId: defaultCustomerId,
      quotationId: defaultQuotationId,
      taskId: defaultTaskId,
    },
  });

  const { isDirty, resetDirty } = useDirtyForm(form, form.formState.defaultValues);

  const onSubmit = (data: ReturnType<typeof JSON.parse>) => {
    // Combine date and time into a single Date object for startTime
    const [timeStr, period] = data.time.split(" ");
    const [hours, minutes] = (timeStr || "10:00").split(":");
    let hoursInt = parseInt(hours || "10");
    if (period === "PM" && hoursInt !== 12) hoursInt += 12;
    if (period === "AM" && hoursInt === 12) hoursInt = 0;
    
    const startTime = new Date(data.date);
    startTime.setHours(hoursInt, parseInt(minutes || "0"), 0, 0);
    
    const isLog = activeTab === "log";
    const duration = isLog ? Number(data.duration) : 30;

    const endTime = new Date(startTime);
    endTime.setMinutes(endTime.getMinutes() + duration);

    // Date/Time validation for today's past times
    if (!isLog) {
      const now = new Date();
      if (startTime.toDateString() === now.toDateString() && startTime < now) {
        form.setError("time", { message: "Cannot schedule a meeting in the past." });
        return;
      }
    }

    createMeeting({
      title: data.title,
      startTime: startTime.toISOString(),
      endTime: endTime.toISOString(),
      location: null,
      type: "MEETING",
      description: data.notes,
      leadId: data.leadId,
      customerId: data.customerId,
      quotationId: data.quotationId,
      taskId: data.taskId,
      isLog: isLog,
      duration: duration,
      notes: data.notes,
    }, {
      onSuccess: () => {
        resetDirty(form.getValues());
        onSuccess?.();
      }
    });
  };

  if (!hasCrmRelation) {
    return (
      <div className="p-4 mb-4 text-sm text-amber-800 rounded-lg bg-amber-50">
        <p className="font-medium">No CRM Relation Found</p>
        <p>This task or context is not linked to a Lead, Customer, or Deal. Please link a CRM record before scheduling a meeting.</p>
        <div className="mt-4 flex justify-end">
          <Button type="button" variant="outline" onClick={onCancel}>Close</Button>
        </div>
      </div>
    );
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <Tabs value={activeTab} onValueChange={(val) => {
          setActiveTab(val as "schedule" | "log");
          form.clearErrors();
        }}>
          <TabsList className="w-full grid grid-cols-2">
            <TabsTrigger value="schedule">Schedule Meeting</TabsTrigger>
            <TabsTrigger value="log">Log Meeting</TabsTrigger>
          </TabsList>
          
          <div className="mt-6 space-y-6">
            <FormInput name="title" label="Meeting Title" placeholder="e.g. Discovery Call" />
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {activeTab === "schedule" ? (
                <FormDatePicker 
                  name="date" 
                  label="Date" 
                  disabled={(date) => {
                    const today = new Date();
                    today.setHours(0, 0, 0, 0);
                    return date < today; // Disable past dates
                  }} 
                />
              ) : (
                <FormDatePicker 
                  name="date" 
                  label="Date" 
                  disabled={(date) => {
                    const tomorrow = new Date();
                    tomorrow.setHours(24, 0, 0, 0);
                    return date >= tomorrow; // Disable future dates
                  }} 
                />
              )}
              
              <FormInput name="time" label="Time (e.g., 10:00 AM)" placeholder="10:00 AM" />
            </div>

            {activeTab === "log" && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormInput name="duration" label="Duration (minutes)" placeholder="30" />
                <FormInput name="outcome" label="Outcome" placeholder="e.g. Discussed pricing" />
              </div>
            )}
            
            <FormTextarea 
              name="notes" 
              label="Notes" 
              placeholder={activeTab === "schedule" ? "Agenda or any additional details..." : "Meeting notes..."} 
            />
          </div>
        </Tabs>

        <div className="flex justify-end gap-3 pt-4 border-t border-border">
          <Button type="button" variant="outline" onClick={onCancel} disabled={isPending}>
            Cancel
          </Button>
          <FormSubmitButton
            isDirty={isDirty}
            isPending={isPending}
            loadingText={activeTab === "schedule" ? "Scheduling..." : "Logging..."}
          >
            {activeTab === "schedule" ? "Schedule Meeting" : "Log Meeting"}
          </FormSubmitButton>
        </div>
      </form>
    </Form>
  );
};

"use client";

import React, { useState, useEffect } from "react";
import { useForm, useFieldArray, useWatch } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Form, FormField, FormItem, FormLabel, FormControl, FormMessage } from "@/shared/ui/form";
import { FormInput, FormSelect, FormDatePicker } from "@/shared/components/form-fields";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { FormSubmitButton } from "@/shared/components/form-submit-button";
import { useDirtyForm } from "@/shared/hooks/use-dirty-form";
import { useCreateQuotation, useUpdateQuotation, useLeads } from "@/shared/hooks/use-crm";
import { useCurrency } from "@/shared/hooks/use-currency";
import { Plus, Trash2, ArrowRight, ArrowLeft } from "lucide-react";
import { LeadType } from "@/shared/types/lead";
import { QuotationType } from "@/shared/types/quotation";

// Using a local schema tailored for this multi-step form, and parsing the backend schema when submitting
const itemSchema = z.object({
  name: z.string().min(1, "Item name is required"),
  quantity: z.coerce.number().min(1, "Qty > 0"),
  price: z.coerce.number().min(0, "Price >= 0"),
  discount: z.coerce.number().min(0).default(0),
});

const quoteFormSchema = z.object({
  leadId: z.string().min(1, "Please select a Deal"),
  client: z.string().min(1, "Client name is required"),
  items: z.array(itemSchema).min(1, "At least one item is required"),
  validTill: z.date(),
  notes: z.string().optional(),
});

type QuoteFormValues = z.infer<typeof quoteFormSchema>;

interface QuoteFormProps {
  initialData?: QuotationType;
  onSuccess?: () => void;
  onCancel?: () => void;
}

export const QuoteForm = ({ initialData, onSuccess, onCancel }: QuoteFormProps) => {
  const [step, setStep] = useState(1);
  const createQuote = useCreateQuotation();
  const updateQuote = useUpdateQuotation();
  const { currencySymbol, formatCurrency } = useCurrency();
  const { data: leadsData } = useLeads();
  const leads = Array.isArray(leadsData?.leads) ? leadsData.leads : [];

  const defaultDate = new Date();
  defaultDate.setDate(defaultDate.getDate() + 15);

  const form = useForm<QuoteFormValues>({
    resolver: zodResolver(quoteFormSchema) as ReturnType<typeof JSON.parse>,
    defaultValues: initialData ? {
      leadId: initialData.leadId || "",
      client: initialData.client || "",
      items: (initialData.items || []).map((item: ReturnType<typeof JSON.parse>) => ({
        name: item.name,
        quantity: item.quantity,
        price: item.price,
        discount: item.discount || 0
      })),
      validTill: initialData.validTillValue ? new Date(initialData.validTillValue) : defaultDate,
      notes: initialData.notes || "",
    } : {
      leadId: "",
      client: "",
      items: [{ name: "", quantity: 1, price: 0, discount: 0 }],
      validTill: defaultDate,
      notes: "",
    },
  });

  const { isDirty, resetDirty } = useDirtyForm(form, form.formState.defaultValues as QuoteFormValues);
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: "items",
  });

  // Watch for deal selection to auto-fill client
  const selectedLeadId = useWatch({ control: form.control, name: "leadId" });
  useEffect(() => {
    if (selectedLeadId && leads.length > 0) {
      const lead = leads.find((l: LeadType) => l.id === selectedLeadId);
      if (lead) {
        form.setValue("client", lead.company || lead.name, { shouldValidate: true });
      }
    }
  }, [selectedLeadId, leads, form]);

  // Watch items to calculate totals
  const items = useWatch({ control: form.control, name: "items" });
  const subtotal = items?.reduce((sum, item) => sum + (Number(item.quantity) * Number(item.price)), 0) || 0;
  const totalDiscount = items?.reduce((sum, item) => sum + Number(item.discount), 0) || 0;
  const grandTotal = subtotal - totalDiscount;

  const onSubmit = async (data: QuoteFormValues) => {
    try {
      const payload = {
        leadId: data.leadId,
        client: data.client,
        amount: String(grandTotal),
        discount: totalDiscount,
        items: data.items.map(item => ({ ...item, total: item.quantity * item.price })),
        validTill: data.validTill ? data.validTill.toISOString() : undefined,
        notes: data.notes,
      };

      if (initialData) {
        await updateQuote.mutateAsync({
          id: initialData.id,
          data: payload,
        });
      } else {
        await createQuote.mutateAsync({
          ...payload,
          status: "DRAFT",
        });
      }
      
      resetDirty(form.getValues());
      onSuccess?.();
    } catch (_error) {
      // Error handled by hook

    }
  };

  const nextStep = async () => {
    let isValid = false;
    if (step === 1) {
      isValid = await form.trigger(["leadId", "client"]);
    } else if (step === 2) {
      isValid = await form.trigger(["items"]);
    }
    if (isValid) setStep(step + 1);
  };

  const prevStep = () => setStep(step - 1);

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        
        {/* Step Indicator */}
        <div className="flex items-center justify-between mb-8 relative">
          <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-1 bg-muted rounded-full overflow-hidden">
            <div 
              className="h-full bg-primary transition-all duration-300"
              style={{ width: `${((step - 1) / 2) * 100}%` }}
            />
          </div>
          {[1, 2, 3].map((num) => (
            <div 
              key={num} 
              className={`relative z-10 w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors border-2
                ${step >= num ? 'bg-primary text-primary-foreground border-primary' : 'bg-background text-muted-foreground border-muted'}
              `}
            >
              {num}
            </div>
          ))}
        </div>

        {/* Step 1: Select Deal */}
        {step === 1 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
            <div>
              <h3 className="text-lg font-bold">Select Deal</h3>
              <p className="text-sm text-muted-foreground mb-4">Choose a pipeline deal to create this quotation for.</p>
            </div>
            <FormSelect 
              name="leadId" 
              label="Related Deal *" 
              options={leads.map((l: LeadType) => ({
                label: `${l.company || l.name} (${formatCurrency(l.valueAmount || Number(String(l.value).replace(/[^0-9.-]+/g,"")))})`,
                value: l.id
              }))} 
            />
            <FormInput name="client" label="Customer / Company Name *" placeholder="Auto-filled from Deal" />
          </div>
        )}

        {/* Step 2: Line Items */}
        {step === 2 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
            <div>
              <h3 className="text-lg font-bold">Quotation Items</h3>
              <p className="text-sm text-muted-foreground mb-4">Add products or services.</p>
            </div>
            
            <div className="space-y-3">
              {fields.map((field, index) => (
                <div key={field.id} className="flex gap-2 items-start p-3 bg-muted/30 rounded-xl border border-border">
                  <div className="flex-1 space-y-3">
                    <FormField
                      control={form.control as ReturnType<typeof JSON.parse>}
                      name={`items.${index}.name`}
                      render={({ field }) => (
                        <FormItem>
                          <FormControl><Input placeholder="Product/Service Description" {...field} className="h-9" /></FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <div className="grid grid-cols-3 gap-2">
                      <FormField
                        control={form.control as ReturnType<typeof JSON.parse>}
                        name={`items.${index}.quantity`}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[10px]">Quantity</FormLabel>
                            <FormControl><Input type="number" min="1" {...field} className="h-9" /></FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control as ReturnType<typeof JSON.parse>}
                        name={`items.${index}.price`}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[10px]">Unit Price</FormLabel>
                            <FormControl><Input type="number" min="0" step="0.01" {...field} className="h-9" /></FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={form.control as ReturnType<typeof JSON.parse>}
                        name={`items.${index}.discount`}
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel className="text-[10px]">Discount</FormLabel>
                            <FormControl><Input type="number" min="0" step="0.01" {...field} className="h-9" /></FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </div>
                  <Button 
                    type="button" 
                    variant="ghost" 
                    size="icon" 
                    className="h-9 w-9 text-muted-foreground hover:text-destructive shrink-0 mt-1"
                    onClick={() => remove(index)}
                    disabled={fields.length === 1}
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              ))}
            </div>
            
            <Button 
              type="button" 
              variant="outline" 
              size="sm" 
              className="w-full h-9 border-dashed mt-2"
              onClick={() => append({ name: "", quantity: 1, price: 0, discount: 0 })}
            >
              <Plus className="w-4 h-4 mr-2" /> Add Item
            </Button>

            <div className="p-4 bg-muted/40 rounded-xl mt-4 border border-border">
              <div className="flex justify-between text-sm mb-2">
                <span className="text-muted-foreground">Subtotal</span>
                <span className="font-semibold">{currencySymbol}{subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm mb-3">
                <span className="text-muted-foreground">Total Discount</span>
                <span className="font-semibold text-rose-500">-{currencySymbol}{totalDiscount.toFixed(2)}</span>
              </div>
              <div className="h-px bg-border w-full mb-3" />
              <div className="flex justify-between items-center">
                <span className="font-bold">Grand Total</span>
                <span className="text-xl font-black text-primary">{currencySymbol}{grandTotal.toFixed(2)}</span>
              </div>
            </div>
          </div>
        )}

        {/* Step 3: Final Details */}
        {step === 3 && (
          <div className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-300">
            <div>
              <h3 className="text-lg font-bold">Final Details</h3>
              <p className="text-sm text-muted-foreground mb-4">Set validity and add optional notes.</p>
            </div>
            <FormDatePicker 
              name="validTill" 
              label="Valid Until *" 
              disabled={(date) => date < new Date(new Date().setHours(0,0,0,0))} 
            />
            <FormField
              control={form.control as ReturnType<typeof JSON.parse>}
              name="notes"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Terms & Conditions / Notes</FormLabel>
                  <FormControl>
                    <textarea 
                      className="flex min-h-[100px] w-full rounded-xl border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
                      placeholder="Enter specific terms for this quotation..."
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>
        )}

        <div className="flex justify-between pt-6 border-t border-border">
          {step > 1 ? (
            <Button type="button" variant="outline" onClick={prevStep} className="h-10">
              <ArrowLeft className="w-4 h-4 mr-2" /> Back
            </Button>
          ) : (
            <Button type="button" variant="ghost" onClick={onCancel} className="h-10 text-muted-foreground">
              Cancel
            </Button>
          )}

          {step < 3 ? (
            <Button type="button" onClick={nextStep} className="h-10 px-8">
              Continue <ArrowRight className="w-4 h-4 ml-2" />
            </Button>
          ) : (
            <FormSubmitButton
              isDirty={isDirty}
              isPending={createQuote.isPending}
              loadingText="Generating..."
              className="h-10 px-8"
            >
              Generate Quote
            </FormSubmitButton>
          )}
        </div>
      </form>
    </Form>
  );
};

