                <Mail className="w-3.5 h-3.5" /> Email
              </Button>
              <Button variant="outline" size="sm" className="flex-1 gap-2 h-9 text-xs" onClick={(e) => handleAction(e, "Call Initiated", lead.name, lead)}>
                <Phone className="w-3.5 h-3.5" /> Call
