"use client";

import { useState, useMemo, useCallback } from "react";
import { LeadType } from "@/shared/types/lead";
import { useDeleteLead } from "@/shared/hooks/use-crm";
import { toast } from "sonner";

export type SortConfig = {
  key: "name" | "valueAmount" | "activity";
  direction: "asc" | "desc" | "newest" | "oldest" | "upcoming" | "overdue";
} | null;

export type FilterConfig = {
  stage: string;
  priority: string;
  activity: string;
};

const isOverdue = (dateStr: string | null | undefined) => {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return date < today;
};

const isToday = (dateStr: string | null | undefined) => {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  const today = new Date();
  return date.toDateString() === today.toDateString();
};

const isTomorrow = (dateStr: string | null | undefined) => {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  return date.toDateString() === tomorrow.toDateString();
};

const isThisWeek = (dateStr: string | null | undefined) => {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  const today = new Date();
  const firstDay = new Date(today.setDate(today.getDate() - today.getDay()));
  const lastDay = new Date(today.setDate(today.getDate() - today.getDay() + 6));
  return date >= firstDay && date <= lastDay;
};

export function useLeads(leads: LeadType[]) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  
  const [filters, setFilters] = useState<FilterConfig>({
    stage: "All Stages",
    priority: "All Priorities",
    activity: "All Activity"
  });

  const [isDeletingBulk, setIsDeletingBulk] = useState(false);
  const deleteLeadMutation = useDeleteLead();

  const filteredAndSortedLeads = useMemo(() => {
    let result = [...leads];

    // 1. Apply Filters
    if (filters.stage !== "All Stages") {
      result = result.filter(lead => lead.stage === filters.stage);
    }

    if (filters.priority !== "All Priorities") {
      result = result.filter(lead => lead.priority === filters.priority);
    }

    if (filters.activity !== "All Activity") {
      result = result.filter(lead => {
        if (filters.activity === "Overdue") return isOverdue(lead.followUpAt);
        if (filters.activity === "Today") return isToday(lead.followUpAt);
        if (filters.activity === "Tomorrow") return isTomorrow(lead.followUpAt);
        if (filters.activity === "This Week") return isThisWeek(lead.followUpAt);
        if (filters.activity === "No Follow-up Scheduled") return !lead.followUpAt;
        if (filters.activity === "No Activity") return !lead.lastActivity && !lead.updatedAt;
        return true;
      });
    }

    // 2. Apply Sorting
    if (sortConfig) {
      result.sort((a, b) => {
        if (sortConfig.key === "name") {
          const aVal = a.name.toLowerCase();
          const bVal = b.name.toLowerCase();
          if (aVal < bVal) return sortConfig.direction === "asc" ? -1 : 1;
          if (aVal > bVal) return sortConfig.direction === "asc" ? 1 : -1;
          return 0;
        }
        if (sortConfig.key === "valueAmount") {
          const aVal = a.valueAmount || 0;
          const bVal = b.valueAmount || 0;
          return sortConfig.direction === "desc" ? bVal - aVal : aVal - bVal;
        }
        if (sortConfig.key === "activity") {
          const aDate = new Date(a.updatedAt || a.createdAt || 0).getTime();
          const bDate = new Date(b.updatedAt || b.createdAt || 0).getTime();
          const aFollowUp = a.followUpAt ? new Date(a.followUpAt).getTime() : Infinity;
          const bFollowUp = b.followUpAt ? new Date(b.followUpAt).getTime() : Infinity;

          if (sortConfig.direction === "newest") return bDate - aDate;
          if (sortConfig.direction === "oldest") return aDate - bDate;
          if (sortConfig.direction === "upcoming") return aFollowUp - bFollowUp;
          if (sortConfig.direction === "overdue") {
            const aIsOverdue = isOverdue(a.followUpAt);
            const bIsOverdue = isOverdue(b.followUpAt);
            if (aIsOverdue && !bIsOverdue) return -1;
            if (!aIsOverdue && bIsOverdue) return 1;
            return aFollowUp - bFollowUp;
          }
        }
        return 0;
      });
    }

    return result;
  }, [leads, sortConfig, filters]);

  const handleSort = (key: NonNullable<SortConfig>["key"], direction?: NonNullable<SortConfig>["direction"]) => {
    if (direction) {
      setSortConfig({ key: key as ReturnType<typeof JSON.parse>, direction });
      return;
    }
    
    // Default toggles for simple sorts if no specific direction is provided
    setSortConfig((prev) => {
      if (prev?.key === key) {
        if (key === "name") return prev.direction === "asc" ? { key, direction: "desc" } : null;
        if (key === "valueAmount") return prev.direction === "desc" ? { key, direction: "asc" } : null;
      }
      if (key === "name") return { key, direction: "asc" };
      if (key === "valueAmount") return { key, direction: "desc" };
      if (key === "activity") return { key, direction: "newest" };
      return null;
    });
  };

  const updateFilter = (key: keyof FilterConfig, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
  };

  const clearFilters = useCallback(() => {
    setFilters({
      stage: "All Stages",
      priority: "All Priorities",
      activity: "All Activity"
    });
    setSortConfig(null);
  }, []);

  const hasActiveFilters = 
    filters.stage !== "All Stages" || 
    filters.priority !== "All Priorities" || 
    filters.activity !== "All Activity" ||
    sortConfig !== null;

  const toggleSelectAll = () => {
    if (selectedIds.length === filteredAndSortedLeads.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(filteredAndSortedLeads.map(l => l.id));
    }
  };

  const toggleSelect = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(selectedIds.filter(i => i !== id));
    } else {
      setSelectedIds([...selectedIds, id]);
    }
  };

  const toggleExpand = (id: string) => {
    setExpandedId(expandedId === id ? null : id);
  };

  const handleDelete = (id: string, name: string) => {
    deleteLeadMutation.mutate(id, {
      onSuccess: () => {
        toast.error("Lead Deleted", {
          description: `${name} has been removed from the CRM.`,
        });
      }
    });
  };

  const handleBulkDelete = async (ids: string[]) => {
    setIsDeletingBulk(true);
    try {
      await Promise.all(ids.map(id => deleteLeadMutation.mutateAsync(id)));
      toast.error("Leads Deleted", {
        description: `${ids.length} leads have been removed from the CRM.`,
      });
      setSelectedIds([]);
    } catch (error) {
      toast.error("Error", {
        description: "Failed to delete some leads.",
      });
    } finally {
      setIsDeletingBulk(false);
    }
  };

  return {
    sortedLeads: filteredAndSortedLeads,
    selectedIds,
    setSelectedIds,
    expandedId,
    sortConfig,
    filters,
    hasActiveFilters,
    updateFilter,
    clearFilters,
    handleSort,
    toggleSelectAll,
    toggleSelect,
    toggleExpand,
    handleDelete,
    handleBulkDelete,
    isDeletingBulk,
  };
}

"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { PipelineLeadType } from "@/shared/types/pipeline";
import { useUpdatePipelineItem } from "@/shared/hooks/use-crm";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { useCurrency } from "@/shared/hooks/use-currency";
import { DollarSign, IndianRupee, Clock, Check, Save } from "lucide-react";
import { Button } from "@/shared/ui/button";
import { toast } from "sonner";

interface DealDrawerProps {
  item: PipelineLeadType | null;
  isOpen: boolean;
  onClose: () => void;
  onStageChange?: (deal: PipelineLeadType, newStage: string) => void;
}

export function DealDrawer({ item, isOpen, onClose, onStageChange }: DealDrawerProps) {
  const { mutate: updateDeal, isPending } = useUpdatePipelineItem();
  const { formatCurrency, currency } = useCurrency();
  const CurrencyIcon = currency === "INR" ? IndianRupee : DollarSign;
  
  // Local state for editing
  const [formData, setFormData] = useState<Partial<PipelineLeadType>>({});
  const [prevItemId, setPrevItemId] = useState<string | undefined>(item?.id);

  // Sync item to formData on open (during render as recommended to avoid cascading renders)
  if (item?.id !== prevItemId) {
    setPrevItemId(item?.id);
    setFormData({});
  }

  if (!item) return null;

  const currentData = { ...item, ...formData };

  const stageToProbability: Record<string, number> = {
    "NEW": 10,
    "CONTACTED": 25,
    "PROPOSAL_SENT": 50,
    "WON": 100,
    "LOST": 0,
  };

  const hasChanges = Object.keys(formData).length > 0;

  const handleChange = (field: keyof PipelineLeadType, value: string | number) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = () => {
    const payload = {
      name: currentData.name,
      company: currentData.company,
      value: currentData.valueAmount,
      priority: currentData.priority,
    };

    // If stage was changed in the drawer, we save the other fields first,
    // then trigger the standard stage change flow (which handles Won/Lost modals)
    if (currentData.stage && currentData.stage !== item.stage && onStageChange) {
      updateDeal({
        id: item.id,
        data: payload
      }, {
        onSuccess: () => {
          toast.success("Deal updated successfully");
          onStageChange(item, currentData.stage as string);
        }
      });
      return;
    }

    updateDeal({
      id: item.id,
      data: payload
    }, {
      onSuccess: () => {
        toast.success("Deal updated successfully");
        onClose();
      }
    });
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent aria-describedby={undefined} className="sm:max-w-[500px] p-0 flex flex-col max-h-[90vh] bg-background border-border overflow-hidden rounded-xl">
        <DialogHeader className="p-6 pb-4 border-b border-border">
          <DialogTitle className="text-xl font-bold tracking-tight">Deal Details</DialogTitle>
          <div className="flex gap-2 mt-3">
             <div className="text-xs px-2.5 py-1 bg-emerald-500/10 text-emerald-600 rounded-md font-bold">{currentData.stage}</div>
             <div className="text-xs px-2.5 py-1 bg-orange-500/10 text-orange-600 rounded-md font-bold">{currentData.priority} Priority</div>
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto">
          <Tabs defaultValue="overview" className="w-full h-full flex flex-col">
            <div className="px-6 pt-4 border-b border-border bg-background sticky top-0 z-10">
              <TabsList className="w-full flex items-center justify-start bg-transparent p-0 rounded-none h-auto gap-2 pb-4 overflow-x-auto border-none">
                <TabsTrigger value="overview" className="rounded-full text-xs font-bold px-4 py-1.5 border border-transparent data-[state=active]:border-primary/50 data-[state=active]:text-foreground data-[state=active]:bg-background data-[state=active]:shadow-sm text-muted-foreground bg-transparent shadow-none">Overview</TabsTrigger>
                <TabsTrigger value="activities" className="rounded-full text-xs font-bold px-4 py-1.5 border border-transparent data-[state=active]:border-primary/50 data-[state=active]:text-foreground data-[state=active]:bg-background data-[state=active]:shadow-sm text-muted-foreground bg-transparent shadow-none">Activities</TabsTrigger>
                <TabsTrigger value="tasks" className="rounded-full text-xs font-bold px-4 py-1.5 border border-transparent data-[state=active]:border-primary/50 data-[state=active]:text-foreground data-[state=active]:bg-background data-[state=active]:shadow-sm text-muted-foreground bg-transparent shadow-none">Tasks</TabsTrigger>
                <TabsTrigger value="notes" className="rounded-full text-xs font-bold px-4 py-1.5 border border-transparent data-[state=active]:border-primary/50 data-[state=active]:text-foreground data-[state=active]:bg-background data-[state=active]:shadow-sm text-muted-foreground bg-transparent shadow-none">Notes</TabsTrigger>
              </TabsList>
            </div>

            <TabsContent value="overview" className="p-6 space-y-6 mt-0">
              {/* Editable Fields Grid */}
              <div className="grid grid-cols-2 gap-5">
                <div className="col-span-2 space-y-1.5">
                  <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Deal Name</label>
                  <input 
                    type="text"
                    value={currentData.name}
                    onChange={(e) => handleChange("name", e.target.value)}
                    className="w-full bg-background border border-border rounded-xl px-4 py-2 text-sm font-semibold focus:border-primary outline-none transition-colors"
                  />
                </div>
                
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Company</label>
                  <input 
                    type="text"
                    value={currentData.company}
                    onChange={(e) => handleChange("company", e.target.value)}
                    className="w-full bg-background border border-border rounded-xl px-4 py-2 text-sm font-semibold focus:border-primary outline-none transition-colors"
                  />
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Value</label>
                  <div className="relative">
                    <CurrencyIcon className="w-4 h-4 text-muted-foreground absolute left-3 top-1/2 -translate-y-1/2" />
                    <input 
                      type="number"
                      value={currentData.valueAmount || 0}
                      onChange={(e) => handleChange("valueAmount", Number(e.target.value))}
                      className="w-full bg-background border border-border rounded-xl pl-9 pr-4 py-2 text-sm font-semibold focus:border-primary outline-none transition-colors"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Stage</label>
                  <select
                    value={currentData.stage || item.stage}
                    onChange={(e) => {
                      const newStage = e.target.value;
                      handleChange("stage", newStage);
                      handleChange("probability", stageToProbability[newStage] || 0);
                    }}
                    className="w-full bg-background border border-border rounded-xl px-4 py-2 text-sm font-semibold focus:border-primary outline-none transition-colors"
                  >
                    <option value="NEW">New Lead</option>
                    <option value="CONTACTED">Contacted</option>
                    <option value="PROPOSAL_SENT">Proposal Sent</option>
                    <option value="WON">Won</option>
                    <option value="LOST">Lost</option>
                  </select>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Priority</label>
                  <select
                    value={currentData.priority}
                    onChange={(e) => handleChange("priority", e.target.value)}
                    className="w-full bg-background border border-border rounded-xl px-4 py-2 text-sm font-semibold focus:border-primary outline-none transition-colors"
                  >
                    <option value="LOW">Low</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="HIGH">High</option>
                  </select>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Probability (%)</label>
                  <input 
                    type="number"
                    min="0" max="100"
                    value={currentData.probability || 0}
                    onChange={(e) => handleChange("probability", Number(e.target.value))}
                    className="w-full bg-background border border-border rounded-xl px-4 py-2 text-sm font-semibold focus:border-primary outline-none transition-colors"
                  />
                </div>
              </div>
            </TabsContent>

            <TabsContent value="activities" className="p-6">
              <div className="flex flex-col items-center justify-center text-center py-12 border-2 border-dashed border-border rounded-xl bg-muted/10">
                <Clock className="w-8 h-8 text-muted-foreground mb-3" />
                <p className="text-sm font-bold text-foreground">No recent activities</p>
                <p className="text-xs text-muted-foreground mt-1">Activities will appear here once logged.</p>
              </div>
            </TabsContent>

            <TabsContent value="tasks" className="p-6">
               <div className="flex flex-col items-center justify-center text-center py-12 border-2 border-dashed border-border rounded-xl bg-muted/10">
                <Check className="w-8 h-8 text-muted-foreground mb-3" />
                <p className="text-sm font-bold text-foreground">No tasks scheduled</p>
              </div>
            </TabsContent>

            <TabsContent value="notes" className="p-6">
               <textarea 
                  placeholder="Type a note..."
                  className="w-full h-32 bg-muted/30 border border-border rounded-xl p-4 text-sm font-medium focus:border-primary outline-none transition-colors resize-none mb-4"
               />
               <Button className="w-full font-bold">Add Note</Button>
            </TabsContent>
          </Tabs>
        </div>

        <div className="p-4 border-t border-border bg-background">
           <Button onClick={handleSave} disabled={isPending || !hasChanges} className="w-full font-bold gap-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl">
             <Save className="w-4 h-4" /> {isPending ? "Saving..." : "Save Changes"}
           </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { 
  Badge 
} from "@/shared/ui/badge";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import { Button } from "@/shared/ui/button";
import { 
  MoreHorizontal, 
  FileText, 
  Send, 
  Download, 
  ExternalLink, 
  Trash2, 
  Copy,
  Clock,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  Edit,
  Check,
  X
} from "lucide-react";
import { useRouter } from "next/navigation";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuTrigger,
  DropdownMenuSeparator
} from "@/shared/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import { QuotationType } from "@/shared/types/quotation";
import { motion, AnimatePresence } from "framer-motion";
import { useState, useMemo } from "react";
import QuotationPreview from "./QuotationPreview";
import { 
  CRMDataTable, 
  CRMTableHeader, 
  CRMTableBody, 
  CRMTableRow, 
  CRMTableCell, 
  CRMTableHeaderCell,
  CRMSortIndicator,
} from "@/shared/components/crm";
import { cn } from "@/shared/lib/utils";
import { toast } from "sonner";
import { useDeleteQuotation, useUpdateQuotationStatus } from "@/shared/hooks/use-crm";
import { useCurrency } from "@/shared/hooks/use-currency";

interface QuotationsTableProps {
  quotations: QuotationType[];
}

type SortConfig = {
  key: keyof QuotationType;
  direction: "asc" | "desc";
} | null;

const ProbabilityIndicator = ({ value }: { value: number }) => {
  const color = value > 80 ? "text-success" : value > 60 ? "text-warning" : "text-muted-foreground";
  return (
    <div className="flex items-center gap-2 group/prob">
      <div className="relative w-8 h-8">
        <svg className="w-full h-full" viewBox="0 0 36 36">
          <path
            className="text-muted/30"
            strokeDasharray="100, 100"
            stroke="currentColor"
            strokeWidth="3"
            fill="none"
            d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
          />
          <motion.path
            initial={{ strokeDasharray: "0, 100" }}
            animate={{ strokeDasharray: `${value}, 100` }}
            transition={{ duration: 1.5, ease: "easeOut" }}
            className={cn(color)}
            stroke="currentColor"
            strokeWidth="3"
            strokeLinecap="round"
            fill="none"
            d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
          />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center text-[9px] font-bold">
          {value}%
        </div>
      </div>
      <span className={cn("text-[10px] font-bold uppercase tracking-wider opacity-0 group-hover/prob:opacity-100 transition-opacity", color)}>
        Prob.
      </span>
    </div>
  );
};

const QuotationsTable = ({ quotations }: QuotationsTableProps) => {
  const [selectedQuote, setSelectedQuote] = useState<QuotationType | null>(null);
  const [deletingQuote, setDeletingQuote] = useState<QuotationType | null>(null);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { mutate: deleteQuotationMutation } = useDeleteQuotation();
  const { mutate: updateStatusMutation } = useUpdateQuotationStatus();
  const { formatCurrency } = useCurrency();

  const sortedQuotations = useMemo(() => {
    if (!sortConfig) return quotations;
    return [...quotations].sort((a, b) => {
      let aVal: string | number = (a[sortConfig.key] as string | number) ?? "";
      let bVal: string | number = (b[sortConfig.key] as string | number) ?? "";
      
      if (sortConfig.key === "amount" as keyof QuotationType) {
        aVal = a.amountValue ?? 0;
        bVal = b.amountValue ?? 0;
      }
      
      if (aVal < bVal) return sortConfig.direction === "asc" ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });
  }, [quotations, sortConfig]);

  const handleSort = (key: keyof QuotationType) => {
    setSortConfig((prev) => {
      if (prev?.key === key) {
        if (prev.direction === "asc") return { key, direction: "desc" };
        return null;
      }
      return { key, direction: "asc" };
    });
  };

  const handleDelete = (e: React.MouseEvent | Event, quote: QuotationType) => {
    e.stopPropagation();
    setDeletingQuote(quote);
  };

  const handleAction = (action: string, quote: QuotationType) => {
    if (action === "Download") {
      window.open(`/quotations/${quote.id}/pdf`, '_blank');
      return;
    }
    if (action === "MarkSent") {
      updateStatusMutation({ id: quote.id, status: "SENT" });
      return;
    }
    if (action === "MarkAccepted") {
      updateStatusMutation({ id: quote.id, status: "ACCEPTED" });
      return;
    }
    if (action === "MarkRejected") {
      updateStatusMutation({ id: quote.id, status: "REJECTED" });
      return;
    }
    toast.info(`${action} clicked for ${quote.quoteId}`);
  };

  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const router = useRouter();

  const totalPages = Math.ceil(sortedQuotations.length / rowsPerPage);
  const paginatedQuotations = sortedQuotations.slice(
    (currentPage - 1) * rowsPerPage,
    currentPage * rowsPerPage
  );

  return (
    <div className="flex-auto flex flex-col min-h-0 relative">
      <div className="flex flex-col bg-card rounded-xl border border-border shadow-sm overflow-hidden h-auto max-h-[calc(100vh-360px)]">
      <CRMDataTable containerClassName="border-0 shadow-none rounded-none flex-auto h-full overflow-auto" className="w-full">
        <CRMTableHeader className="sticky top-0 z-10 bg-card shadow-sm">
          <CRMTableRow>
            <CRMTableHeaderCell 
              className="hidden sm:table-cell cursor-pointer group select-none"
              onClick={() => handleSort("quoteId")}
            >
              <div className="flex items-center gap-2">
                Quote No <CRMSortIndicator active={sortConfig?.key === "quoteId"} direction={sortConfig?.direction} />
              </div>
            </CRMTableHeaderCell>
            <CRMTableHeaderCell 
              className="cursor-pointer group select-none bg-card"
              onClick={() => handleSort("client")}
            >
              <div className="flex items-center gap-2">
                Customer <CRMSortIndicator active={sortConfig?.key === "client"} direction={sortConfig?.direction} />
              </div>
            </CRMTableHeaderCell>
            <CRMTableHeaderCell className="hidden md:table-cell bg-card">
              Related Deal
            </CRMTableHeaderCell>
            <CRMTableHeaderCell 
              className="hidden md:table-cell cursor-pointer group select-none"
              onClick={() => handleSort("amount")}
            >
              <div className="flex items-center gap-2">
                Quote Value <CRMSortIndicator active={sortConfig?.key === "amount"} direction={sortConfig?.direction} />
              </div>
            </CRMTableHeaderCell>
            <CRMTableHeaderCell 
              className="cursor-pointer group select-none bg-card"
              onClick={() => handleSort("status")}
            >
              <div className="flex items-center gap-2">
                Status <CRMSortIndicator active={sortConfig?.key === "status"} direction={sortConfig?.direction} />
              </div>
            </CRMTableHeaderCell>
            <CRMTableHeaderCell className="hidden lg:table-cell bg-card">Valid Until</CRMTableHeaderCell>
            <CRMTableHeaderCell className="hidden xl:table-cell bg-card">Owner</CRMTableHeaderCell>
            <CRMTableHeaderCell className="hidden xl:table-cell bg-card">Last Updated</CRMTableHeaderCell>
            <CRMTableHeaderCell className="text-right bg-card">Actions</CRMTableHeaderCell>
          </CRMTableRow>
        </CRMTableHeader>

        <CRMTableBody>
          <AnimatePresence mode="popLayout">
            {paginatedQuotations.map((quote) => (
              <CRMTableRow
                key={quote.id}
                onClick={() => setSelectedQuote(quote)}
              >
                <CRMTableCell className="hidden sm:table-cell">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 rounded-lg bg-muted flex items-center justify-center border border-border transition-colors">
                      <FileText className="w-4 h-4 text-muted-foreground" />
                    </div>
                    <div>
                      <p className="font-semibold text-foreground text-sm tracking-tight transition-colors">{quote.quoteId}</p>
                      <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider mt-0.5">May 2026</p>
                    </div>
                  </div>
                </CRMTableCell>

                <CRMTableCell>
                  <div className="flex items-center gap-3">
                    <Avatar className="w-9 h-9 rounded-lg border border-border bg-muted flex items-center justify-center font-bold text-xs">
                      <AvatarFallback>
                        {quote.client.split(' ').map((n: string) => n[0]).join('')}
                      </AvatarFallback>
                    </Avatar>
                    <div>
                      <p className="font-semibold text-foreground text-sm tracking-tight">{quote.client}</p>
                      <div className="flex items-center gap-1.5 mt-0.5">
                        <span className="text-muted-foreground text-[10px] font-bold uppercase tracking-wider">{"System"}</span>
                        <span className="hidden sm:inline w-1 h-1 rounded-full bg-border" />
                        <span className="hidden sm:inline text-[9px] font-bold text-primary uppercase tracking-wider">VIP</span>
                      </div>
                    </div>
                  </div>
                </CRMTableCell>

                <CRMTableCell className="hidden md:table-cell">
                  <span className="font-semibold text-foreground text-sm">{quote.leadName || quote.client}</span>
                </CRMTableCell>

                <CRMTableCell className="hidden md:table-cell">
                  <div className="flex flex-col">
                    <span className="font-bold text-foreground text-sm tracking-tight">{formatCurrency(quote.amountValue)}</span>
                  </div>
                </CRMTableCell>

                <CRMTableCell onClick={(e) => e.stopPropagation()}>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Badge variant="outline" className={cn(
                        "border-none px-3 py-0.5 rounded-full font-bold text-[10px] uppercase tracking-widest shadow-sm cursor-pointer hover:opacity-80 transition-opacity flex items-center gap-1 w-fit select-none",
                        quote.status === "DRAFT" && "bg-slate-500/10 text-slate-600 border-slate-500/20",
                        quote.status === "SENT" && "bg-blue-500/10 text-blue-600 border-blue-500/20",
                        quote.status === "ACCEPTED" && "bg-emerald-500/10 text-emerald-600 border-emerald-500/20",
                        quote.status === "REJECTED" && "bg-rose-500/10 text-rose-600 border-rose-500/20",
                        quote.status === "EXPIRED" && "bg-slate-800/10 text-slate-700 border-slate-800/20",
                        !['DRAFT', 'SENT', 'ACCEPTED', 'REJECTED', 'EXPIRED'].includes(quote.status) && 'bg-muted text-muted-foreground'
                      )}>
                        {quote.status}
                        <ChevronDown className="w-3 h-3 opacity-60" />
                      </Badge>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="w-36">
                      <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "DRAFT" })} className="text-xs font-semibold cursor-pointer">
                        <span className="w-2 h-2 rounded-full bg-slate-500 mr-2" /> Draft
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "SENT" })} className="text-xs font-semibold cursor-pointer">
                        <span className="w-2 h-2 rounded-full bg-blue-500 mr-2" /> Sent
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "ACCEPTED" })} className="text-xs font-semibold cursor-pointer text-emerald-600">
                        <span className="w-2 h-2 rounded-full bg-emerald-500 mr-2" /> Accepted
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "REJECTED" })} className="text-xs font-semibold cursor-pointer text-rose-600">
                        <span className="w-2 h-2 rounded-full bg-rose-500 mr-2" /> Rejected
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "EXPIRED" })} className="text-xs font-semibold cursor-pointer">
                        <span className="w-2 h-2 rounded-full bg-slate-800 mr-2" /> Expired
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </CRMTableCell>

                <CRMTableCell className="hidden lg:table-cell">
                  <span className="text-sm font-medium text-muted-foreground whitespace-nowrap">{quote.validTill}</span>
                </CRMTableCell>

                <CRMTableCell className="hidden xl:table-cell">
                  <div className="flex items-center gap-2">
                    <Avatar className="w-6 h-6 border border-border">
                      <AvatarFallback className="text-[10px]">OS</AvatarFallback>
                    </Avatar>
                    <span className="text-sm font-medium text-muted-foreground">System</span>
                  </div>
                </CRMTableCell>

                <CRMTableCell className="hidden xl:table-cell">
                  <div className="flex items-center gap-1.5 text-muted-foreground">
                    <Clock className="w-3.5 h-3.5" />
                    <span className="text-[11px] font-medium whitespace-nowrap">{quote.lastActivity}</span>
                  </div>
                </CRMTableCell>

                <CRMTableCell className="text-right">
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                      <Button variant="ghost" size="icon" className="h-8 w-8 rounded-lg text-muted-foreground hover:text-foreground">
                        <MoreHorizontal className="w-4 h-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-48">
                      <DropdownMenuItem onClick={() => setSelectedQuote(quote)}>
                        <ExternalLink className="w-3.5 h-3.5 mr-2" /> View Details
                      </DropdownMenuItem>

                      <DropdownMenuItem onClick={() => router.push(`?edit=${quote.id}`)}>
                        <Edit className="w-3.5 h-3.5 mr-2" /> Edit Quote
                      </DropdownMenuItem>

                      <DropdownMenuItem onClick={() => handleAction("Download", quote)}>
                        <Download className="w-3.5 h-3.5 mr-2" /> Download PDF
                      </DropdownMenuItem>
                      
                      <DropdownMenuItem onClick={() => handleAction("Duplicate", quote)}>
                        <Copy className="w-3.5 h-3.5 mr-2" /> Duplicate
                      </DropdownMenuItem>

                      <DropdownMenuSeparator />

                      {quote.status !== "SENT" && (
                        <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "SENT" })}>
                          <Send className="w-3.5 h-3.5 mr-2" /> Mark as Sent
                        </DropdownMenuItem>
                      )}
                      {quote.status !== "ACCEPTED" && (
                        <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "ACCEPTED" })} className="text-emerald-600 focus:text-emerald-600 focus:bg-emerald-50">
                          <Check className="w-3.5 h-3.5 mr-2" /> Mark as Accepted
                        </DropdownMenuItem>
                      )}
                      {quote.status !== "REJECTED" && (
                        <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "REJECTED" })} className="text-rose-600 focus:text-rose-600 focus:bg-rose-50">
                          <X className="w-3.5 h-3.5 mr-2" /> Mark as Rejected
                        </DropdownMenuItem>
                      )}
                      {quote.status !== "DRAFT" && (
                        <DropdownMenuItem onClick={() => updateStatusMutation({ id: quote.id, status: "DRAFT" })}>
                          <FileText className="w-3.5 h-3.5 mr-2" /> Mark as Draft
                        </DropdownMenuItem>
                      )}

                      <DropdownMenuSeparator />
                      <DropdownMenuItem onClick={(e) => handleDelete(e, quote)} variant="destructive">
                        <Trash2 className="w-3.5 h-3.5 mr-2" /> Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </CRMTableCell>
              </CRMTableRow>
            ))}
          </AnimatePresence>
        </CRMTableBody>
      </CRMDataTable>
      </div>

      {sortedQuotations.length > 10 && (
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 mt-4 bg-card border border-border rounded-xl p-4 shadow-sm flex-shrink-0">
          <div className="text-sm text-muted-foreground font-medium w-full md:w-auto text-center md:text-left">
            Showing <span className="font-bold text-foreground">{(currentPage - 1) * rowsPerPage + 1}</span>–<span className="font-bold text-foreground">{Math.min(currentPage * rowsPerPage, sortedQuotations.length)}</span> of <span className="font-bold text-foreground">{new Intl.NumberFormat().format(sortedQuotations.length)}</span> Quotes
          </div>
          
          <div className="flex flex-col sm:flex-row items-center gap-4 sm:gap-6 w-full md:w-auto justify-center md:justify-end">
            <div className="flex items-center gap-2">
              <span className="text-sm text-muted-foreground font-medium">Rows per page:</span>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="sm" className="h-8 gap-1 font-semibold">
                    {rowsPerPage} <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="min-w-[4rem]">
                  {[10, 25, 50, 100].map(size => (
                    <DropdownMenuItem key={size} onClick={() => { setRowsPerPage(size); setCurrentPage(1); }} className="font-medium text-sm cursor-pointer hover:bg-muted">
                      {size}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>

            <div className="flex items-center gap-1.5">
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
              >
                <ChevronsLeft className="w-4 h-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
              >
                <ChevronLeft className="w-4 h-4" />
              </Button>
              <div className="flex items-center justify-center px-4 text-sm font-semibold text-foreground min-w-[5rem]">
                Page {currentPage}
              </div>
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
              >
                <ChevronRight className="w-4 h-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages}
              >
                <ChevronsRight className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </div>
      )}

      <QuotationPreview 
        quotation={selectedQuote}
        isOpen={!!selectedQuote}
        onClose={() => setSelectedQuote(null)}
      />

      <AlertDialog open={!!deletingQuote} onOpenChange={(open) => !open && setDeletingQuote(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the quotation <strong>{deletingQuote?.quoteId}</strong>. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction 
              variant="destructive" 
              onClick={() => {
                if (deletingQuote) {
                  deleteQuotationMutation(deletingQuote.id);
                  setDeletingQuote(null);
                }
              }}
            >
              Delete Quotation
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default QuotationsTable;

