"use client";

import React, { useState, useMemo } from "react";
import { useForm, useFieldArray } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/shared/ui/dialog";
import { Form, FormControl, FormField, FormItem, FormMessage } from "@/shared/ui/form";
import { Input } from "@/shared/ui/input";
import { Textarea } from "@/shared/ui/textarea";
import { Button } from "@/shared/ui/button";
import { Label } from "@/shared/ui/label";
import { FormSubmitButton } from "@/shared/components/form-submit-button";
import { UnsavedWarning } from "@/shared/components/unsaved-warning";
import { useDirtyForm } from "@/shared/hooks/use-dirty-form";
import { useUpdateTask, useEmployees, useLeads, useCustomers, useQuotations } from "@/shared/hooks/use-crm";
import { useAuth } from "@/features/auth/components/auth-provider";
import { TaskType } from "@/shared/types/task";
import {
  CheckSquare,
  ListTodo,
  Plus,
  Trash2,
  Loader2,
  Paperclip,
  AlertCircle,
  FileText,
  Search,
  ChevronRight,
  X,
} from "lucide-react";
import { cn } from "@/shared/lib/utils";

// ─── Schema (essential fields only) ───

const taskFormSchema = z.object({
  title: z.string().min(2, "Title must be at least 2 characters"),
  description: z.string().optional().default(""),
  assignedToId: z.string().min(1, "Please assign this task"),
  priority: z.enum(["URGENT", "HIGH", "MEDIUM", "LOW"]).default("MEDIUM"),
  dueDate: z.string().min(1, "Due date is required"),
  checklist: z
    .array(z.object({ id: z.string(), title: z.string().min(1), completed: z.boolean().default(false) }))
    .default([]),
});

type TaskFormValues = z.infer<typeof taskFormSchema>;

// ─── Constants ───

const PRIORITY_OPTIONS = [
  { value: "HIGH", label: "High", dot: "bg-rose-500" },
  { value: "MEDIUM", label: "Medium", dot: "bg-amber-500" },
  { value: "LOW", label: "Low", dot: "bg-blue-500" },
] as const;

type RelationType = "lead" | "customer" | "quotation";

interface RelatedRecord {
  type: RelationType;
  id: string;
  label: string;
  sub?: string;
}

// ─── Component ───

interface EditTaskModalProps {
  task: TaskType | null;
  isOpen: boolean;
  onClose: () => void;
  onSuccess?: () => void;
}

export const EditTaskModal: React.FC<EditTaskModalProps> = ({ task, isOpen, onClose, onSuccess }) => {
  const { user } = useAuth();
  const { mutate: updateTask, isPending } = useUpdateTask();
  const { data: employeesData } = useEmployees();
  const { data: leadsData } = useLeads();
  const { data: customersData } = useCustomers();
  const { data: quotationsData } = useQuotations();

  const employees  = employeesData?.employees || [];
  const leads      = leadsData?.leads || [];
  const customers  = customersData?.customers || [];
  const quotations = quotationsData?.quotations || [];

  const [activeTab, setActiveTab] = useState<"general" | "checklist">("general");
  const [checklistInput, setChecklistInput] = useState("");
  const [attachments, setAttachments] = useState<{ id: string; fileName: string; fileSize: number }[]>([]);

  // Related record state
  const [relatedRecord, setRelatedRecord] = useState<RelatedRecord | null>(null);
  const [recordSearch, setRecordSearch] = useState("");
  const [recordDropdownOpen, setRecordDropdownOpen] = useState(false);

  const [showWarning, setShowWarning] = useState(false);

  const defaultDueDate = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().slice(0, 16);

  const form = useForm<TaskFormValues>({
    resolver: zodResolver(taskFormSchema) as ReturnType<typeof JSON.parse>,
    defaultValues: {
      title: "",
      description: "",
      assignedToId: user?.id || "",
      priority: "MEDIUM",
      dueDate: defaultDueDate,
      checklist: [],
    },
  });

  const { isDirty, resetDirty } = useDirtyForm(form, form.formState.defaultValues as TaskFormValues, {
    externalOriginalValues: {
      attachments: task?.attachments || [],
      relatedRecord: (() => {
        if (!task) return null;
        if (task.relatedLead) return { type: "lead", id: task.relatedLead.id, label: task.relatedLead.name, sub: task.relatedLead.company || "" };
        if (task.relatedCustomer) return { type: "customer", id: task.relatedCustomer.id, label: task.relatedCustomer.name, sub: task.relatedCustomer.company || "" };
        if (task.relatedQuotation) return { type: "quotation", id: task.relatedQuotation.id, label: `#${task.relatedQuotation.quoteNumber}`, sub: (task.relatedQuotation as ReturnType<typeof JSON.parse>).client };
        return null;
      })()
    },
    externalValues: { attachments, relatedRecord }
  });

  React.useEffect(() => {
    if (task && isOpen) {
      let formattedDueDate = defaultDueDate;
      if (task.dueDate) {
        const parsedDate = new Date(task.dueDate);
        if (!isNaN(parsedDate.getTime())) {
          formattedDueDate = parsedDate.toISOString().slice(0, 16);
        }
      }

      form.reset({
        title: task.title,
        description: task.description || "",
        assignedToId: task.assignedTo?.id || user?.id || "",
        priority: task.priority as ReturnType<typeof JSON.parse>,
        dueDate: formattedDueDate,
        checklist: task.checklist || [],
      });
      setAttachments(task.attachments || []);
      
      if (task.relatedLead) {
        setRelatedRecord({ type: "lead", id: task.relatedLead.id, label: task.relatedLead.name, sub: task.relatedLead.company || "" });
      } else if (task.relatedCustomer) {
        setRelatedRecord({ type: "customer", id: task.relatedCustomer.id, label: task.relatedCustomer.name, sub: task.relatedCustomer.company || "" });
      } else if (task.relatedQuotation) {
        setRelatedRecord({ type: "quotation", id: task.relatedQuotation.id, label: `#${task.relatedQuotation.quoteNumber}`, sub: (task.relatedQuotation as ReturnType<typeof JSON.parse>).client });
      } else {
        setRelatedRecord(null);
      }
    }
  }, [task, isOpen, user?.id, form, defaultDueDate]);

  const { fields: checklistFields, append: appendChecklist, remove: removeChecklist } = useFieldArray({
    control: form.control,
    name: "checklist",
  });

  // ─── Related Record search results ───

  const recordResults = useMemo(() => {
    const q = recordSearch.toLowerCase().trim();
    const results: RelatedRecord[] = [];

    leads.forEach((l: ReturnType<typeof JSON.parse>) => {
      if (!q || l.name?.toLowerCase().includes(q) || l.company?.toLowerCase().includes(q)) {
        results.push({ type: "lead", id: l.id, label: l.name, sub: l.company });
      }
    });
    customers.forEach((c: ReturnType<typeof JSON.parse>) => {
      if (!q || c.name?.toLowerCase().includes(q) || c.company?.toLowerCase().includes(q)) {
        results.push({ type: "customer", id: c.id, label: c.name, sub: c.company });
      }
    });
    quotations.forEach((qt: ReturnType<typeof JSON.parse>) => {
      if (!q || qt.quoteNumber?.toLowerCase().includes(q) || qt.client?.toLowerCase().includes(q)) {
        results.push({ type: "quotation", id: qt.id, label: `#${qt.quoteNumber}`, sub: qt.client });
      }
    });

    return results.slice(0, 8);
  }, [recordSearch, leads, customers, quotations]);

  // ─── Handlers ───

  const handleAddChecklist = () => {
    const v = checklistInput.trim();
    if (v) {
      appendChecklist({ id: `c-${Date.now()}`, title: v, completed: false });
      setChecklistInput("");
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const next = Array.from(files).map((f) => ({
      id: `a-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      fileName: f.name,
      fileSize: f.size,
    }));
    setAttachments((prev) => [...prev, ...next]);
  };

  const resetForm = () => {
    form.reset();
    setRelatedRecord(null);
    setRecordSearch("");
    setAttachments([]);
    setChecklistInput("");
    setActiveTab("general");
  };

  const onSubmit = (data: TaskFormValues) => {
    if (!task) return;
    const payload: ReturnType<typeof JSON.parse> = {
      title: data.title,
      description: data.description || null,
      assignedToId: data.assignedToId,
      priority: data.priority,
      dueDate: new Date(data.dueDate).toISOString(),
      checklist: data.checklist,
      attachments,
      relatedLeadId: relatedRecord?.type === "lead" ? relatedRecord.id : null,
      relatedCustomerId: relatedRecord?.type === "customer" ? relatedRecord.id : null,
      relatedQuotationId: relatedRecord?.type === "quotation" ? relatedRecord.id : null,
    };

    updateTask(
      { id: task.id, data: payload },
      {
        onSuccess: () => {
          resetDirty();
          onSuccess?.();
          resetForm();
          onClose();
        },
      }
    );
  };

  const watchedDueDate = form.watch("dueDate");
  const isPastDue = watchedDueDate ? new Date(watchedDueDate) < new Date() : false;
  const hasErrors = Object.keys(form.formState.errors).length > 0;

  const RECORD_TYPE_LABELS: Record<RelationType, { label: string; color: string }> = {
    lead: { label: "Lead", color: "text-violet-600 bg-violet-50 dark:text-violet-400 dark:bg-violet-500/10" },
    customer: { label: "Customer", color: "text-emerald-600 bg-emerald-50 dark:text-emerald-400 dark:bg-emerald-500/10" },
    quotation: { label: "Quote", color: "text-blue-600 bg-blue-50 dark:text-blue-400 dark:bg-blue-500/10" },
  };

  const handleOpenChange = (open: boolean) => {
    if (!open && isDirty) {
      setShowWarning(true);
      return;
    }
    if (!open) {
      resetForm();
      onClose();
    }
  };

  return (
    <>
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className="sm:max-w-[520px] bg-background border border-border shadow-2xl rounded-xl overflow-hidden p-0 flex flex-col max-h-[90vh]">
        {/* ── HEADER ── */}
        <div className="px-6 py-4 border-b border-border bg-muted/30 shrink-0">
          <DialogHeader>
            <div className="flex items-center gap-3">
              <div className="flex size-9 items-center justify-center rounded-lg border border-border bg-background text-muted-foreground shadow-sm shrink-0">
                <CheckSquare className="size-4 text-primary" />
              </div>
              <div>
                <DialogTitle className="text-xl font-bold tracking-tight text-foreground">
                  Edit Task
                </DialogTitle>
                <DialogDescription className="mt-1 text-sm text-muted-foreground">
                  Update the task details below.
                </DialogDescription>
              </div>
            </div>
          </DialogHeader>
        </div>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="flex-1 flex flex-col min-h-0">
            {/* ── TAB BAR ── */}
            <div className="flex border-b border-border bg-background px-6 shrink-0">
              {([
                { key: "general" as const, label: "General", icon: FileText },
                { key: "checklist" as const, label: "Checklist", icon: ListTodo },
              ]).map((tab) => {
                const Icon = tab.icon;
                const isActive = activeTab === tab.key;
                return (
                  <button
                    key={tab.key}
                    type="button"
                    onClick={() => setActiveTab(tab.key)}
                    className={cn(
                      "flex items-center gap-1.5 px-4 py-2.5 text-[11px] font-bold uppercase tracking-widest border-b-2 transition-colors",
                      isActive
                        ? "border-primary text-primary"
                        : "border-transparent text-muted-foreground hover:text-foreground"
                    )}
                  >
                    <Icon className="size-3.5" />
                    {tab.label}
                    {tab.key === "checklist" && checklistFields.length > 0 && (
                      <span className="ml-1 text-[9px] font-bold bg-primary/10 text-primary rounded-full size-4 inline-flex items-center justify-center">
                        {checklistFields.length}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>

            {/* ── BODY ── */}
            <div className="flex-1 overflow-y-auto p-6">
              {/* ===== GENERAL TAB ===== */}
              {activeTab === "general" && (
                <div className="space-y-4">
                  {/* Title */}
                  <FormField
                    control={form.control}
                    name="title"
                    render={({ field }) => (
                      <FormItem className="space-y-1.5">
                        <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                          Task Title <span className="text-destructive">*</span>
                        </Label>
                        <FormControl>
                          <Input
                            placeholder="e.g. Follow up with Acme Corp"
                            className="h-10 text-sm font-medium"
                            autoFocus
                            {...field}
                          />
                        </FormControl>
                        <FormMessage className="text-xs" />
                      </FormItem>
                    )}
                  />

                  {/* Description */}
                  <FormField
                    control={form.control}
                    name="description"
                    render={({ field }) => (
                      <FormItem className="space-y-1.5">
                        <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                          Description
                        </Label>
                        <FormControl>
                          <Textarea
                            placeholder="Brief notes or context..."
                            className="resize-none min-h-[72px] text-sm"
                            {...field}
                          />
                        </FormControl>
                      </FormItem>
                    )}
                  />

                  {/* Assign To + Priority — side by side */}
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="assignedToId"
                      render={({ field }) => (
                        <FormItem className="space-y-1.5">
                          <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                            Assign To <span className="text-destructive">*</span>
                          </Label>
                          <FormControl>
                            <select
                              {...field}
                              className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-medium shadow-sm transition-colors focus:outline-none focus:ring-2 focus:ring-ring"
                            >
                              <option value="">Select...</option>
                              {employees.map((emp: ReturnType<typeof JSON.parse>) => (
                                <option key={emp.id} value={emp.id || emp.userId}>
                                  {emp.name}
                                </option>
                              ))}
                              {employees.length === 0 && user?.id && (
                                <option value={user.id}>{user.name || "Me"}</option>
                              )}
                            </select>
                          </FormControl>
                          <FormMessage className="text-xs" />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="priority"
                      render={({ field }) => (
                        <FormItem className="space-y-1.5">
                          <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                            Priority
                          </Label>
                          <FormControl>
                            <select
                              {...field}
                              className="h-10 w-full rounded-lg border border-input bg-background px-3 text-sm font-medium shadow-sm transition-colors focus:outline-none focus:ring-2 focus:ring-ring"
                            >
                              {PRIORITY_OPTIONS.map((p) => (
                                <option key={p.value} value={p.value}>
                                  {p.label}
                                </option>
                              ))}
                            </select>
                          </FormControl>
                        </FormItem>
                      )}
                    />
                  </div>

                  {/* Due Date */}
                  <FormField
                    control={form.control}
                    name="dueDate"
                    render={({ field }) => (
                      <FormItem className="space-y-1.5">
                        <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                          Due Date <span className="text-destructive">*</span>
                        </Label>
                        <FormControl>
                          <Input type="datetime-local" className="h-10 text-sm" {...field} />
                        </FormControl>
                        {isPastDue && (
                          <p className="text-[11px] text-amber-600 dark:text-amber-400 flex items-center gap-1 font-semibold">
                            <AlertCircle className="size-3" />
                            This date is in the past
                          </p>
                        )}
                        <FormMessage className="text-xs" />
                      </FormItem>
                    )}
                  />

                  {/* Related Record — single searchable selector */}
                  <div className="space-y-1.5">
                    <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                      Related Record
                    </Label>

                    {relatedRecord ? (
                      <div className="h-10 rounded-lg border border-border bg-muted/10 px-3 flex items-center justify-between">
                        <div className="flex items-center gap-2 min-w-0">
                          <span className={cn(
                            "text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded",
                            RECORD_TYPE_LABELS[relatedRecord.type].color
                          )}>
                            {RECORD_TYPE_LABELS[relatedRecord.type].label}
                          </span>
                          <span className="text-sm font-medium text-foreground truncate">
                            {relatedRecord.label}
                          </span>
                          {relatedRecord.sub && (
                            <span className="text-xs text-muted-foreground truncate">
                              — {relatedRecord.sub}
                            </span>
                          )}
                        </div>
                        <button
                          type="button"
                          onClick={() => setRelatedRecord(null)}
                          className="text-muted-foreground hover:text-destructive shrink-0"
                        >
                          <X className="size-3.5" />
                        </button>
                      </div>
                    ) : (
                      <div className="relative">
                        <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground pointer-events-none" />
                          <Input
                            placeholder="Search leads, customers, quotes..."
                            value={recordSearch}
                            onChange={(e) => { setRecordSearch(e.target.value); setRecordDropdownOpen(true); }}
                            onFocus={() => setRecordDropdownOpen(true)}
                            onBlur={() => setTimeout(() => setRecordDropdownOpen(false), 200)}
                            className="h-10 pl-9 text-sm"
                          />
                        </div>

                        {recordDropdownOpen && recordResults.length > 0 && (
                          <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-popover border border-border rounded-lg shadow-lg max-h-52 overflow-y-auto">
                            {recordResults.map((r) => (
                              <button
                                key={`${r.type}-${r.id}`}
                                type="button"
                                onMouseDown={(e) => e.preventDefault()}
                                onClick={() => {
                                  setRelatedRecord(r);
                                  setRecordSearch("");
                                  setRecordDropdownOpen(false);
                                }}
                                className="w-full px-3 py-2.5 text-left hover:bg-muted/60 flex items-center gap-2 transition-colors first:rounded-t-lg last:rounded-b-lg"
                              >
                                <span className={cn(
                                  "text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded shrink-0",
                                  RECORD_TYPE_LABELS[r.type].color
                                )}>
                                  {RECORD_TYPE_LABELS[r.type].label}
                                </span>
                                <span className="text-sm font-medium text-foreground truncate">{r.label}</span>
                                {r.sub && (
                                  <span className="text-xs text-muted-foreground truncate ml-auto">{r.sub}</span>
                                )}
                              </button>
                            ))}
                          </div>
                        )}

                        {recordDropdownOpen && recordSearch.trim() && recordResults.length === 0 && (
                          <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-popover border border-border rounded-lg shadow-lg px-3 py-4 text-center">
                            <p className="text-xs text-muted-foreground">No records found</p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* ===== CHECKLIST TAB ===== */}
              {activeTab === "checklist" && (
                <div className="space-y-5">
                  {/* Subtask Checklist */}
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest">
                        Subtasks
                      </Label>
                      <span className="text-[11px] font-bold text-muted-foreground">
                        {checklistFields.length} {checklistFields.length === 1 ? "item" : "items"}
                      </span>
                    </div>

                    <div className="flex gap-2">
                      <Input
                        placeholder="Add a subtask..."
                        value={checklistInput}
                        onChange={(e) => setChecklistInput(e.target.value)}
                        onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); handleAddChecklist(); } }}
                        className="h-9 text-sm flex-1"
                        autoFocus
                      />
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={handleAddChecklist}
                        className="h-9 px-3 text-xs font-bold"
                      >
                        <Plus className="size-3.5" />
                      </Button>
                    </div>

                    <div className="space-y-1.5 max-h-48 overflow-y-auto">
                      {checklistFields.map((item, idx) => (
                        <div
                          key={item.id}
                          className="flex items-center justify-between h-9 px-3 rounded-lg border border-border bg-muted/10 group"
                        >
                          <div className="flex items-center gap-2 min-w-0">
                            <ChevronRight className="size-3 text-muted-foreground shrink-0" />
                            <span className="text-sm font-medium text-foreground truncate">{item.title}</span>
                          </div>
                          <button
                            type="button"
                            onClick={() => removeChecklist(idx)}
                            className="opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-destructive transition-opacity shrink-0"
                          >
                            <Trash2 className="size-3.5" />
                          </button>
                        </div>
                      ))}
                      {checklistFields.length === 0 && (
                        <p className="text-[11px] text-muted-foreground italic text-center py-6">
                          No subtasks yet — add one above
                        </p>
                      )}
                    </div>
                  </div>

                  {/* Attachments */}
                  <div className="space-y-2 pt-4 border-t border-border">
                    <Label className="text-[11px] font-bold text-muted-foreground uppercase tracking-widest flex items-center gap-1.5">
                      <Paperclip className="size-3" /> Attachments
                    </Label>

                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="w-full h-9 border-dashed text-xs text-muted-foreground gap-2 font-semibold"
                      onClick={() => document.getElementById("task-file-input")?.click()}
                    >
                      <Paperclip className="size-3.5" /> Attach Files
                    </Button>
                    <input
                      id="task-file-input"
                      type="file"
                      multiple
                      onChange={handleFileUpload}
                      className="hidden"
                    />

                    {attachments.length > 0 && (
                      <div className="space-y-1.5">
                        {attachments.map((att) => (
                          <div
                            key={att.id}
                            className="flex items-center justify-between h-9 px-3 rounded-lg border border-border bg-muted/10 group"
                          >
                            <div className="flex items-center gap-2 min-w-0">
                              <Paperclip className="size-3.5 text-muted-foreground shrink-0" />
                              <span className="text-sm font-medium text-foreground truncate">{att.fileName}</span>
                              <span className="text-[10px] text-muted-foreground shrink-0">
                                {Math.round(att.fileSize / 1024)} KB
                              </span>
                            </div>
                            <button
                              type="button"
                              onClick={() => setAttachments((prev) => prev.filter((a) => a.id !== att.id))}
                              className="opacity-0 group-hover:opacity-100 text-muted-foreground hover:text-destructive transition-opacity shrink-0"
                            >
                              <Trash2 className="size-3.5" />
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* ── FOOTER ── */}
            <div className="shrink-0 px-6 py-4 border-t border-border bg-muted/10 flex items-center justify-between">
              <div>
                {hasErrors && (
                  <p className="text-xs text-destructive font-semibold flex items-center gap-1">
                    <AlertCircle className="size-3.5" />
                    Check required fields
                  </p>
                )}
              </div>
              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => handleOpenChange(false)}
                  disabled={isPending}
                  className="h-9 px-4 text-xs font-semibold"
                >
                  Cancel
                </Button>
                <FormSubmitButton
                  isDirty={isDirty}
                  isPending={isPending}
                  className="h-10 px-5 gap-2 font-semibold shadow-sm w-full sm:w-auto"
                >
                  {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckSquare className="w-4 h-4" />}
                  Save Changes
                </FormSubmitButton>
              </div>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
    <UnsavedWarning 
      open={showWarning} 
      onOpenChange={setShowWarning} 
      onConfirm={() => { setShowWarning(false); resetForm(); onClose(); }} 
      onCancel={() => setShowWarning(false)} 
    />
    </>
  );
};

"use client";

import type { ComponentType } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/shared/ui/dialog";
import { TaskType } from "@/shared/types/task";
import { Badge } from "@/shared/ui/badge";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import {
  AlertCircle,
  Calendar,
  CheckCircle2,
  Clock,
  Loader2,
  Sparkles,
  Tag,
  X,
} from "lucide-react";
import { useState } from "react";
import { Button } from "@/shared/ui/button";
import { ScrollArea } from "@/shared/ui/scroll-area";
import { Progress } from "@/shared/ui/progress";
import { ActivityTimeline } from "@/shared/components/crm";
import { cn } from "@/shared/lib/utils";

import { useUpdateTask } from "@/shared/hooks/use-crm";

interface TaskDetailsModalProps {
  task: TaskType | null;
  isOpen: boolean;
  onClose: () => void;
  onScheduleMeeting?: (task: TaskType) => void;
}

const TaskDetailsModal = ({
  task,
  isOpen,
  onClose,
  onScheduleMeeting,
}: TaskDetailsModalProps) => {
  const { mutate: updateTask } = useUpdateTask();
  const [isUpdating, setIsUpdating] = useState(false);

  if (!task) return null;

  const collaborators = task.collaborators?.length ?? 0;
  const isCompleted = task?.status === "COMPLETED";
  const statusTone = isCompleted
    ? "text-emerald-600 bg-emerald-500/10 border-emerald-500/20"
    : task.status === "IN_PROGRESS"
      ? "text-blue-600 bg-blue-500/10 border-blue-500/20"
      : "text-amber-600 bg-amber-500/10 border-amber-500/20";

  const activityItems = [
    {
      id: `${task.id}-activity-1`,
      title: "Task created",
      description: `Assigned to ${"Unassigned"} under ${task.category ?? "General"} workspace.`,
      time: "Recently",
      icon: Sparkles,
      iconBg: "bg-primary/10",
      iconColor: "text-primary",
    },
    {
      id: `${task.id}-activity-2`,
      title: "Progress updated",
      description: `${task.progress}% completion tracked against ${task.estimatedTime ?? "4h"} estimate.`,
      time: task.lastActivity ?? "2h ago",
      icon: Clock,
      iconBg: "bg-blue-500/10",
      iconColor: "text-blue-600",
    },
    {
      id: `${task.id}-activity-3`,
      title: isCompleted ? "Task completed" : "Next milestone",
      description: isCompleted
        ? "All checkpoints marked complete and ready for reporting."
        : `Due on ${task.dueDate}. ${task.isOverdue ? "This item needs urgent attention." : "On track with current pace."}`,
      time: "Now",
      icon: isCompleted ? CheckCircle2 : AlertCircle,
      iconBg: isCompleted ? "bg-emerald-500/10" : "bg-amber-500/10",
      iconColor: isCompleted ? "text-emerald-600" : "text-amber-600",
    },
  ];

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent
        showCloseButton={false}
        className="flex flex-col gap-0 overflow-hidden bg-background p-0 sm:max-w-2xl max-h-[90vh]"
      >
        <header className="shrink-0 border-b border-border/60 bg-card/40 px-6 py-5 backdrop-blur-sm">
          <div className="mb-4 flex items-start justify-between gap-4">
            <div className="flex flex-wrap items-center gap-2">
              <Badge
                variant="outline"
                className="border-border/70 bg-background/60 text-[10px] font-semibold uppercase tracking-wide"
              >
                {task.category ?? "General"}
              </Badge>
              <Badge
                className={cn(
                  "border text-[10px] font-semibold uppercase tracking-wide",
                  statusTone,
                )}
              >
                {task.status}
              </Badge>
              {task.isUrgent && (
                <Badge className="border border-rose-500/30 bg-rose-500/10 text-[10px] font-semibold uppercase tracking-wide text-rose-600">
                  Urgent
                </Badge>
              )}
            </div>
            <Button
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="h-8 w-8 rounded-lg text-muted-foreground hover:text-foreground"
              aria-label="Close task details"
            >
              <X className="h-4 w-4" />
            </Button>
          </div>

          <DialogTitle className="text-2xl font-bold leading-tight text-foreground">
            {task.title}
          </DialogTitle>
          <DialogDescription className="mt-2 text-sm text-muted-foreground">
            Managed by {"Unassigned"} • Last updated{" "}
            {task.lastActivity ?? "recently"}
          </DialogDescription>

          <div className="mt-4 flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2 rounded-lg border border-border/60 bg-background/80 px-3 py-2">
              <Avatar className="h-7 w-7 border border-border/60">
                <AvatarFallback className="bg-primary/10 text-[10px] font-bold text-primary">
                  {"Unassigned"
                    .split(" ")
                    .filter(Boolean)
                    .map((name) => name[0])
                    .join("")
                    .slice(0, 2)}
                </AvatarFallback>
              </Avatar>
              <div className="flex flex-col leading-tight">
                <span className="text-xs font-semibold text-foreground">
                  {"Unassigned"}
                </span>
                <span className="text-[10px] uppercase tracking-wide text-muted-foreground">
                  Owner
                </span>
              </div>
            </div>
            <div className="rounded-lg border border-border/60 bg-background/80 px-3 py-2 text-xs font-medium text-muted-foreground">
              Priority:{" "}
              <span className="font-semibold text-foreground">
                {task.priority}
              </span>
            </div>
            <div className="rounded-lg border border-border/60 bg-background/80 px-3 py-2 text-xs font-medium text-muted-foreground">
              Due:{" "}
              <span className="font-semibold text-foreground">
                {task.dueDate}
              </span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-hidden">
          <ScrollArea className="h-full">
            <div className="space-y-6 px-6 py-6 pb-24">
              <section className="rounded-xl border border-border/60 bg-card p-4">
                <div className="mb-4 grid grid-cols-2 gap-3">
                  <StatTile
                    label="Progress"
                    value={`${task.progress}%`}
                    icon={CheckCircle2}
                  />
                  <StatTile
                    label="Attachments"
                    value={String(task.attachmentsCount ?? 0)}
                    icon={Tag}
                  />
                </div>

                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs font-medium text-muted-foreground">
                    <span>Completion</span>
                    <span className="font-semibold text-foreground">
                      {task.progress}%
                    </span>
                  </div>
                  <Progress
                    value={task.progress}
                    className="h-2 bg-muted"
                    indicatorClassName={
                      isCompleted ? "bg-emerald-500" : "bg-primary"
                    }
                  />
                </div>
              </section>

              <section className="rounded-xl border border-border/60 bg-card p-4">
                <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Description
                </h3>
                <p className="text-sm leading-relaxed text-foreground/85">
                  {task.description}
                </p>
                {task.aiSummary && (
                  <div className="mt-4 rounded-lg border border-primary/20 bg-primary/5 p-3">
                    <p className="text-[11px] font-semibold uppercase tracking-wide text-primary">
                      AI Summary
                    </p>
                    <p className="mt-1 text-xs leading-relaxed text-foreground/80">
                      {task.aiSummary}
                    </p>
                  </div>
                )}
                {(task.tags?.length ?? 0) > 0 && (
                  <div className="mt-4 flex flex-wrap gap-2">
                    {task.tags?.map((tag) => (
                      <Badge
                        key={tag}
                        variant="outline"
                        className="border-border/70 bg-background text-[10px] font-medium"
                      >
                        {tag}
                      </Badge>
                    ))}
                  </div>
                )}
              </section>

              <section className="rounded-xl border border-border/60 bg-card p-4">
                <h3 className="mb-4 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                  Activity Timeline
                </h3>
                <ActivityTimeline items={activityItems} className="space-y-6" />
              </section>

              {task.isOverdue && (
                <section className="rounded-xl border border-rose-500/30 bg-rose-500/5 p-4">
                  <div className="flex items-start gap-3">
                    <AlertCircle className="mt-0.5 h-4 w-4 text-rose-600" />
                    <div>
                      <h4 className="text-sm font-semibold text-rose-700">
                        Task is overdue
                      </h4>
                      <p className="mt-1 text-xs text-rose-700/80">
                        Due date has passed. Reprioritize this task or update
                        the schedule.
                      </p>
                    </div>
                  </div>
                </section>
              )}
            </div>
          </ScrollArea>
        </div>

        <footer className="shrink-0 border-t border-border/60 bg-card px-4 py-3 sm:px-6 sm:py-4">
          <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap sm:items-center sm:justify-end sm:gap-3">
            <div className="grid w-full min-w-0 grid-cols-2 gap-2 sm:flex sm:w-auto sm:min-w-0 sm:items-center">
              <Button
                variant="ghost"
                onClick={() => onScheduleMeeting?.(task)}
                className="h-10 w-full min-w-0 px-2 text-xs font-semibold sm:w-auto sm:px-4"
              >
                <Calendar className="h-3.5 w-3.5" />
                <span className="truncate">Schedule Meeting</span>
              </Button>
              <Button
                variant={isCompleted ? "outline" : "default"}
                className="h-10 w-full min-w-0 px-2 text-xs font-semibold sm:w-auto sm:px-5"
                disabled={isUpdating}
                onClick={() => {
                  setIsUpdating(true);
                  updateTask(
                    { id: task.id, data: { status: isCompleted ? "PENDING" : "COMPLETED" } },
                    { onSettled: () => setIsUpdating(false) }
                  );
                }}
              >
                {isUpdating ? <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" /> : null}
                <span className="truncate">
                  {isCompleted ? "Reopen Task" : "Mark Complete"}
                </span>
              </Button>
            </div>
          </div>
        </footer>
      </DialogContent>
    </Dialog>
  );
};

interface StatTileProps {
  label: string;
  value: string;
  icon: ComponentType<{ className?: string }>;
}

const StatTile = ({ label, value, icon: Icon }: StatTileProps) => (
  <div className="rounded-lg border border-border/60 bg-background/60 p-3">
    <div className="mb-2 flex items-center justify-between">
      <span className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
        {label}
      </span>
      <Icon className="h-3.5 w-3.5 text-muted-foreground" />
    </div>
    <p className="text-sm font-semibold text-foreground">{value}</p>
  </div>
);

export default TaskDetailsModal;

"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { TaskType } from "@/shared/types/task";
import { Badge } from "@/shared/ui/badge";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import { 
  MoreHorizontal, 
  MessageSquare,
  Paperclip,
  Trash2,
  Eye,
  Pencil,
  CheckCircle2,
  Calendar,
  Link2,
} from "lucide-react";
import { Button } from "@/shared/ui/button";
import { useDeleteTask, useUpdateTask } from "@/shared/hooks/use-crm";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import { Loader2 } from "lucide-react";
import { cn } from "@/shared/lib/utils";
import { useState } from "react";

interface TaskKanbanCardProps {
  task: TaskType;
  onClick: (task: TaskType) => void;
  isOverlay?: boolean;
  onScheduleMeeting?: (task: TaskType) => void;
  onEditTask?: (task: TaskType) => void;
}

export const TaskKanbanCard = ({ task, onClick, isOverlay, onScheduleMeeting, onEditTask }: TaskKanbanCardProps) => {
  const [isUpdating, setIsUpdating] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const {
    setNodeRef,
    attributes,
    listeners,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: task.id,
    data: {
      type: "Task",
      task,
    },
  });

  const style = {
    transition,
    transform: CSS.Translate.toString(transform),
  };

  const { mutate: deleteTask } = useDeleteTask();
  const { mutate: updateTask } = useUpdateTask();

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    deleteTask(task.id);
  };

  if (isDragging) {
    return (
      <div
        ref={setNodeRef}
        style={style}
        className="opacity-30 bg-muted/40 p-4 rounded-xl border border-dashed border-primary/20 h-[180px]"
      />
    );
  }

  return (
    <div 
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      onClick={() => onClick(task)}
      className={cn(
        "bg-card p-4 rounded-xl border border-border/50 shadow-[var(--crm-card-shadow)] hover:shadow-[var(--crm-card-hover-shadow)] hover:border-primary/20 transition-all cursor-grab active:cursor-grabbing group relative",
        isOverlay && "shadow-elevated border-primary/50 rotate-1 scale-[1.02]"
      )}
    >
      <div className="flex justify-between items-start mb-3">
        <Badge className={cn(
          "px-2 py-0.5 rounded-md font-bold text-[8px] uppercase tracking-widest border-none",
          task.priority === "HIGH" ? "bg-rose-500/10 text-rose-500" : 
          task.priority === "MEDIUM" ? "bg-amber-500/10 text-amber-500" : 
          "bg-blue-500/10 text-blue-500"
        )}>
          {task.priority}
        </Badge>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button 
              variant="ghost" 
              size="icon" 
              onClick={(e) => e.stopPropagation()}
              className="opacity-0 group-hover:opacity-100 h-7 w-7 rounded-lg"
            >
              <MoreHorizontal className="w-3.5 h-3.5 text-muted-foreground" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48 rounded-xl p-2 shadow-premium">
            <DropdownMenuItem
              onClick={(e) => { e.stopPropagation(); onClick(task); }}
              className="rounded-lg gap-2 font-semibold text-xs cursor-pointer"
            >
              <Eye className="w-3.5 h-3.5" /> View
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={(e) => {
                e.stopPropagation();
                onEditTask?.(task);
              }}
              className="rounded-lg gap-2 font-semibold text-xs cursor-pointer"
            >
              <Pencil className="w-3.5 h-3.5" /> Edit
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={(e) => {
                e.stopPropagation();
                setIsUpdating(true);
                updateTask(
                  { id: task.id, data: { status: task.status === "COMPLETED" ? "PENDING" : "COMPLETED" } },
                  { onSettled: () => setIsUpdating(false) }
                );
              }}
              className="rounded-lg gap-2 font-semibold text-xs cursor-pointer"
              disabled={isUpdating}
            >
              {isUpdating ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5" />}
              {task.status === "COMPLETED" ? "Reopen Task" : "Mark Complete"}
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={(e) => {
                e.stopPropagation();
                onScheduleMeeting?.(task);
              }}
              className="rounded-lg gap-2 font-semibold text-xs cursor-pointer"
            >
              <Calendar className="w-3.5 h-3.5" /> Schedule Meeting
            </DropdownMenuItem>
            <DropdownMenuItem 
              onClick={(e) => {
                e.stopPropagation();
                setShowDeleteConfirm(true);
              }}
              className="rounded-lg gap-2 font-semibold text-xs cursor-pointer text-red-600 focus:bg-red-50 focus:text-red-700"
            >
              <Trash2 className="w-3.5 h-3.5" /> Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <AlertDialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <AlertDialogContent onClick={e => e.stopPropagation()}>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the task "{task.title}". This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction 
              variant="destructive"
              disabled={isDeleting}
              onClick={(e) => {
                e.preventDefault();
                setIsDeleting(true);
                deleteTask(task.id, {
                  onSuccess: () => setShowDeleteConfirm(false),
                  onSettled: () => setIsDeleting(false)
                });
              }}
            >
              {isDeleting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <h4 className="font-bold text-foreground group-hover:text-primary transition-colors mb-3 leading-tight tracking-tight text-sm">
        {task.title}
      </h4>

      {(task.relatedLead || task.relatedCustomer) && (
        <div className="mb-4">
          <Badge variant="outline" className="gap-1.5 border-border/70 bg-background/60 text-[10px] text-muted-foreground hover:bg-muted/50 cursor-pointer px-2 py-1 transition-colors">
            <Link2 className="w-3 h-3" />
            <span className="font-semibold text-foreground">
              {task.relatedLead ? "Lead" : "Customer"}
            </span>
            <span>•</span>
            <span className="truncate max-w-[120px]">
              {task.relatedLead?.name || task.relatedCustomer?.name}
            </span>
          </Badge>
        </div>
      )}

      <div className="flex items-center justify-between mt-4 pt-4 border-t border-border/50">
        <div className="flex items-center -space-x-1.5">
          <Avatar className="w-6 h-6 border-2 border-card shadow-sm rounded-lg">
            <AvatarFallback className="text-[8px] font-bold bg-muted text-muted-foreground">
              {"Unassigned".split(' ').map((n: string) => n[0]).join('')}
            </AvatarFallback>
          </Avatar>
          {task.collaborators?.slice(0, 2).map((c: { id: string; name: string }) => (
            <Avatar key={c.id} className="w-6 h-6 border-2 border-card shadow-sm rounded-lg">
              <AvatarFallback className="text-[8px] font-bold bg-primary/15 text-primary">
                {c.name.split(' ').map((n: string) => n[0]).join('')}
              </AvatarFallback>
            </Avatar>
          ))}
        </div>

        <div className="flex items-center gap-3 text-muted-foreground">
          <div className="flex items-center gap-1">
            <MessageSquare className="w-3 h-3" />
            <span className="text-[9px] font-bold uppercase tracking-widest">{task.notesCount || 0}</span>
          </div>
          <div className="flex items-center gap-1">
            <Paperclip className="w-3 h-3" />
            <span className="text-[9px] font-bold uppercase tracking-widest">{task.attachmentsCount || 0}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

"use client";

import { useState } from "react";
import { Badge } from "@/shared/ui/badge";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import { Button } from "@/shared/ui/button";
import { 
  Calendar, CheckCircle2, Eye, MoreHorizontal, 
  Trash2, ChevronDown, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight,
  Pencil, Link2, Download, UserPlus, Loader2
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import { Checkbox } from "@/shared/ui/checkbox";
import { TaskType } from "@/shared/types/task";
import {
  CRMDataTable,
  CRMTableBody,
  CRMTableCell,
  CRMTableHeader,
  CRMTableHeaderCell,
  CRMTableRow,
} from "@/shared/components/crm";
import { cn } from "@/shared/lib/utils";
import { useUpdateTask, useDeleteTask } from "@/shared/hooks/use-crm";
import { toast } from "sonner";
import { motion, AnimatePresence } from "framer-motion";

interface TasksTableProps {
  tasks: TaskType[];
  onTaskClick: (task: TaskType) => void;
  onScheduleMeeting?: (task: TaskType) => void;
  onEditTask?: (task: TaskType) => void;
}

const TasksTable = ({ tasks, onTaskClick, onScheduleMeeting, onEditTask }: TasksTableProps) => {
  const { mutate: updateTask } = useUpdateTask();
  const { mutate: deleteTask } = useDeleteTask();
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [selectedTasks, setSelectedTasks] = useState<Set<string>>(new Set());
  const [updatingTaskId, setUpdatingTaskId] = useState<string | null>(null);
  const [taskToDelete, setTaskToDelete] = useState<TaskType | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const totalPages = Math.ceil(tasks.length / rowsPerPage);
  const paginatedTasks = tasks.slice(
    (currentPage - 1) * rowsPerPage,
    currentPage * rowsPerPage
  );

  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedTasks(new Set(paginatedTasks.map(t => t.id)));
    } else {
      setSelectedTasks(new Set());
    }
  };

  const handleSelectTask = (taskId: string, checked: boolean) => {
    const next = new Set(selectedTasks);
    if (checked) next.add(taskId);
    else next.delete(taskId);
    setSelectedTasks(next);
  };

  const handleBulkComplete = () => {
    selectedTasks.forEach(id => updateTask({ id, data: { status: "COMPLETED" } }));
    setSelectedTasks(new Set());
  };

  const handleBulkDelete = () => {
    if (confirm("Are you sure you want to delete the selected tasks?")) {
      selectedTasks.forEach(id => deleteTask(id));
      setSelectedTasks(new Set());
    }
  };

  const handleExport = () => {
    toast.success(`Exporting ${selectedTasks.size} tasks to CSV...`);
    setSelectedTasks(new Set());
  };

  return (
    <div className="flex-auto flex flex-col min-h-0 relative">
      <AnimatePresence>
        {selectedTasks.size > 0 && (
          <motion.div
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 20, opacity: 0 }}
            className="absolute bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-4 rounded-full border border-border bg-background/95 px-6 py-3 shadow-xl backdrop-blur-md"
          >
            <span className="text-sm font-semibold text-foreground">
              {selectedTasks.size} selected
            </span>
            <div className="h-4 w-px bg-border/60" />
            <div className="flex items-center gap-2">
              <Button size="sm" variant="ghost" className="h-8 gap-2 rounded-full px-4 text-xs font-semibold hover:bg-emerald-500/10 hover:text-emerald-600" onClick={handleBulkComplete}>
                <CheckCircle2 className="h-3.5 w-3.5" /> Complete
              </Button>
              <Button size="sm" variant="ghost" className="h-8 gap-2 rounded-full px-4 text-xs font-semibold hover:bg-blue-500/10 hover:text-blue-600" onClick={() => toast.info("Assign feature coming soon")}>
                <UserPlus className="h-3.5 w-3.5" /> Assign
              </Button>
              <Button size="sm" variant="ghost" className="h-8 gap-2 rounded-full px-4 text-xs font-semibold hover:bg-orange-500/10 hover:text-orange-600" onClick={handleExport}>
                <Download className="h-3.5 w-3.5" /> Export
              </Button>
              <Button size="sm" variant="ghost" className="h-8 gap-2 rounded-full px-4 text-xs font-semibold hover:bg-rose-500/10 hover:text-rose-600" onClick={handleBulkDelete}>
                <Trash2 className="h-3.5 w-3.5" /> Delete
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex flex-col bg-card rounded-xl border border-border shadow-sm overflow-hidden h-auto max-h-[calc(100vh-360px)]">
        <CRMDataTable containerClassName="border-0 shadow-none rounded-none flex-auto h-full overflow-auto" className="w-full">
          <CRMTableHeader className="sticky top-0 z-10 bg-card shadow-sm">
            <CRMTableRow className="h-14 border-b border-border/30 bg-muted/20">
              <CRMTableHeaderCell className="w-[52px] px-5">
                <Checkbox 
                  checked={paginatedTasks.length > 0 && selectedTasks.size === paginatedTasks.length}
                  onCheckedChange={handleSelectAll}
                  className="rounded-md border-muted-foreground/20" 
                />
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="px-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Task
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[130px] px-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Status
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[120px] px-4 text-center text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Priority
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[150px] px-4 text-center text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Due Date
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[160px] px-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Related Record
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[140px] px-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Owner
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[120px] px-4 text-center text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Last Updated
              </CRMTableHeaderCell>
              <CRMTableHeaderCell className="w-[80px] px-5 text-right text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground/60">
                Actions
              </CRMTableHeaderCell>
            </CRMTableRow>
          </CRMTableHeader>

          <CRMTableBody className="divide-y divide-border/15">
            {paginatedTasks.map((task) => (
              <CRMTableRow key={task.id} className="group h-[72px]">
                <CRMTableCell className="px-5">
                  <Checkbox
                    checked={selectedTasks.has(task.id)} 
                    onCheckedChange={(checked: boolean) => handleSelectTask(task.id, checked)}
                    className="rounded-md border-muted-foreground/20"
                  />
                </CRMTableCell>

                <CRMTableCell className="min-w-[280px] px-4">
                  <button
                    type="button"
                    className="flex w-full flex-col gap-1 text-left"
                    onClick={() => onTaskClick(task)}
                  >
                    <div className="flex items-center gap-2">
                      <p className={cn(
                        "line-clamp-1 text-[13px] font-semibold leading-tight tracking-tight text-foreground transition-colors",
                        task.status === "COMPLETED" && "text-muted-foreground line-through"
                      )}>
                        {task.title}
                      </p>
                    </div>
                  </button>
                </CRMTableCell>

                <CRMTableCell className="px-4">
                  <Badge variant="outline" className={cn(
                    "border-border/70 bg-background/60 text-[10px] font-semibold uppercase tracking-wide",
                    task.status === "COMPLETED" && "bg-emerald-500/10 text-emerald-600 border-emerald-500/20",
                    task.status === "PENDING" && "bg-amber-500/10 text-amber-600 border-amber-500/20",
                    task.status === "IN_PROGRESS" && "bg-blue-500/10 text-blue-600 border-blue-500/20"
                  )}>
                    {task.status}
                  </Badge>
                </CRMTableCell>

                <CRMTableCell className="text-center px-4">
                  <span className={cn(
                    "inline-flex min-w-[70px] items-center justify-center rounded-md border px-2 py-0.5 text-[9px] font-bold uppercase tracking-widest",
                    task.priority === "HIGH" && "border-rose-500/25 bg-rose-500/10 text-rose-700",
                    task.priority === "MEDIUM" && "border-amber-500/25 bg-amber-500/10 text-amber-700",
                    task.priority === "LOW" && "border-blue-500/25 bg-blue-500/10 text-blue-700"
                  )}>
                    {task.priority}
                  </span>
                </CRMTableCell>

                <CRMTableCell className="px-4 text-center">
                  <div className="inline-flex items-center gap-1.5 text-[11px] font-semibold text-foreground">
                    <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                    {task.dueDate}
                  </div>
                </CRMTableCell>

                <CRMTableCell className="px-4">
                  {(task.relatedLead || task.relatedCustomer) ? (
                    <Badge variant="outline" className="gap-1.5 border-border/70 bg-background/60 text-[10px] text-muted-foreground px-2 py-1 transition-colors hover:bg-muted/50 cursor-pointer">
                      <Link2 className="w-3 h-3" />
                      <span className="font-semibold text-foreground truncate max-w-[80px]">
                        {task.relatedLead ? task.relatedLead.name : task.relatedCustomer?.name}
                      </span>
                    </Badge>
                  ) : (
                    <span className="text-muted-foreground/40 text-xs">-</span>
                  )}
                </CRMTableCell>

                <CRMTableCell className="px-4">
                  <div className="flex items-center gap-2">
                    <Avatar className="h-6 w-6 border border-border/60">
                      <AvatarFallback className="bg-primary/10 text-[9px] font-bold text-primary">
                        {"U"}
                      </AvatarFallback>
                    </Avatar>
                    <span className="text-[11px] font-semibold text-foreground">
                      Unassigned
                    </span>
                  </div>
                </CRMTableCell>
                
                <CRMTableCell className="px-4 text-center">
                  <span className="text-[10px] font-medium text-muted-foreground">
                    {task.lastActivity ?? "Today"}
                  </span>
                </CRMTableCell>

                <CRMTableCell className="px-5 text-right">
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon-sm" className="text-muted-foreground/70 hover:text-foreground">
                        <MoreHorizontal className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-48 rounded-xl border-border/70 p-1.5 shadow-premium">
                      <DropdownMenuItem onClick={() => onTaskClick(task)} className="gap-2 rounded-lg py-2 text-xs font-medium cursor-pointer">
                        <Eye className="h-4 w-4" /> View
                      </DropdownMenuItem>
                      <DropdownMenuItem 
                        onClick={() => onEditTask?.(task)}
                        className="gap-2 rounded-lg py-2 text-xs font-medium cursor-pointer"
                      >
                        <Pencil className="h-4 w-4" /> Edit
                      </DropdownMenuItem>
                      <DropdownMenuItem 
                        onClick={(e) => {
                          e.preventDefault();
                          setUpdatingTaskId(task.id);
                          updateTask(
                            { id: task.id, data: { status: task.status === "COMPLETED" ? "PENDING" : "COMPLETED" } },
                            { onSettled: () => setUpdatingTaskId(null) }
                          );
                        }} 
                        className="gap-2 rounded-lg py-2 text-xs font-medium cursor-pointer"
                        disabled={updatingTaskId === task.id}
                      >
                        {updatingTaskId === task.id ? (
                          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                        ) : (
                          <CheckCircle2 className="h-4 w-4" /> 
                        )}
                        {task.status === "COMPLETED" ? "Reopen Task" : "Mark Complete"}
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => onScheduleMeeting?.(task)} className="gap-2 rounded-lg py-2 text-xs font-medium cursor-pointer">
                        <Calendar className="h-4 w-4" /> Schedule Meeting
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem 
                        variant="destructive" 
                        className="gap-2 rounded-lg py-2 text-xs font-medium cursor-pointer"
                        onClick={() => setTaskToDelete(task)}
                      >
                        <Trash2 className="h-4 w-4" /> Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </CRMTableCell>
              </CRMTableRow>
            ))}
          </CRMTableBody>
        </CRMDataTable>
      </div>

      {tasks.length > 10 && (
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 mt-4 bg-card border border-border rounded-xl p-4 shadow-sm flex-shrink-0">
          <div className="text-sm text-muted-foreground font-medium w-full md:w-auto text-center md:text-left">
            Showing <span className="font-bold text-foreground">{(currentPage - 1) * rowsPerPage + 1}</span>–<span className="font-bold text-foreground">{Math.min(currentPage * rowsPerPage, tasks.length)}</span> of <span className="font-bold text-foreground">{new Intl.NumberFormat().format(tasks.length)}</span> Tasks
          </div>
          
          <div className="flex flex-col sm:flex-row items-center gap-4 sm:gap-6 w-full md:w-auto justify-center md:justify-end">
            <div className="flex items-center gap-2">
              <span className="text-sm text-muted-foreground font-medium">Rows per page:</span>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline" size="sm" className="h-8 gap-1 font-semibold">
                    {rowsPerPage} <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="min-w-[4rem]">
                  {[10, 25, 50, 100].map(size => (
                    <DropdownMenuItem key={size} onClick={() => { setRowsPerPage(size); setCurrentPage(1); }} className="font-medium text-sm cursor-pointer hover:bg-muted">
                      {size}
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>

            <div className="flex items-center gap-1.5">
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(1)}
                disabled={currentPage === 1}
              >
                <ChevronsLeft className="w-4 h-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
              >
                <ChevronLeft className="w-4 h-4" />
              </Button>
              <div className="flex items-center justify-center px-4 text-sm font-semibold text-foreground min-w-[5rem]">
                Page {currentPage}
              </div>
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
              >
                <ChevronRight className="w-4 h-4" />
              </Button>
              <Button
                variant="outline"
                size="icon"
                className="h-8 w-8 rounded-lg hover:bg-muted hover:text-foreground transition-colors"
                onClick={() => setCurrentPage(totalPages)}
                disabled={currentPage === totalPages}
              >
                <ChevronsRight className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </div>
      )}
      <AlertDialog open={!!taskToDelete} onOpenChange={(open) => !open && setTaskToDelete(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the task "{taskToDelete?.title}". This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction 
              variant="destructive"
              disabled={isDeleting}
              onClick={(e) => {
                e.preventDefault();
                if (!taskToDelete) return;
                setIsDeleting(true);
                deleteTask(taskToDelete.id, {
                  onSuccess: () => {
                    toast.success("Task deleted successfully");
                    setTaskToDelete(null);
                  },
                  onSettled: () => setIsDeleting(false)
                });
              }}
            >
              {isDeleting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

