import { cookies, headers } from "next/headers";
import jwt from "jsonwebtoken";
import { env } from "@/lib/env";
import { ApiError } from "@/lib/api-error";
import prisma from "@/lib/prisma";

interface AuthSession {
  userId: string;
  tenantId: string;
  role: string;
}

export async function getAuthSession(): Promise<AuthSession | null> {
  try {
    const headersList = await headers();
    const userId = headersList.get("x-user-id");
    const tenantId = headersList.get("x-tenant-id");
    const role = headersList.get("x-role");

    if (userId && tenantId && role) {
      return { userId, tenantId, role };
    }

    // Fallback if headers are not set
    const cookieStore = await cookies();
    const token = cookieStore.get("auth_token")?.value;

    if (!token) return null;

    const decoded = jwt.verify(
      token,
      env.JWT_SECRET
    ) as AuthSession;

    return {
      userId: decoded.userId || (decoded as { id?: string }).id || "",
      tenantId: decoded.tenantId,
      role: decoded.role,
    };
   
  } catch (_error) {
    return null;
  }
}

export async function requireRole(allowedRoles: string[]) {
  const session = await getAuthSession();
  
  if (!session) {
    throw new ApiError("Unauthorized", 401);
  }

  if (!allowedRoles.includes(session.role.toUpperCase())) {
    throw new ApiError("Forbidden", 403);
  }

  return session;
}

 
export async function requirePermission(module: string, _action?: string) {
  const session = await getAuthSession();
  
  if (!session) {
    throw new ApiError("Unauthorized", 401);
  }

  // Fetch latest user role and permissions from DB

  const tenantUser = await prisma.tenantUser.findUnique({
    where: { tenantId_userId: { tenantId: session.tenantId, userId: session.userId } },
    include: {
      role: {
        include: {
          permissions: true
        }
      }
    }
  });

  if (!tenantUser) {
    throw new ApiError("Forbidden", 403);
  }

  const roleName = tenantUser.role.name.toUpperCase();
  if (roleName === "SUPER ADMIN" || roleName === "ADMIN") {
    return { ...session, role: tenantUser.role.name };
  }

  const hasPerm = tenantUser.role.permissions.some(
    (rp) => rp.module === module && rp.hasAccess
  );

  if (!hasPerm && !tenantUser.role.isSystem) {
    throw new ApiError(`Forbidden: Missing access to ${module}`, 403);
  }

  return { ...session, role: tenantUser.role.name };
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { verifyJWT } from "@/shared/lib/auth/jwt";
import { AuthService } from "@/services/auth.service";
import { extractClientIp } from "@/shared/lib/auth/utils";

const publicPaths = [
  "/login",
  "/register",
  "/forgot-password",
  "/reset-password",
];

const publicApiPaths = [
  "/api/auth/login",
  "/api/auth/register",
  "/api/auth/logout",
  "/api/auth/forgot-password",
  "/api/auth/reset-password",
];

export async function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl;

  if (
    pathname.startsWith("/_next") ||
    pathname.match(/\.(png|jpg|jpeg|gif|svg|ico)$/) ||
    pathname === "/favicon.ico"
  ) {
    return NextResponse.next();
  }

  const isPublicPath = publicPaths.some(
    (path) => pathname === path || pathname.startsWith(`${path}/`)
  );

  const isPublicApiPath = publicApiPaths.some(
    (path) => pathname === path || pathname.startsWith(`${path}/`)
  );

  const isApiRoute = pathname.startsWith("/api/");

  // CSRF defense-in-depth (OWASP): reject state-changing cross-origin requests.
  // Primary mitigation is SameSite=Lax + HttpOnly cookies (browser never
  // attaches the session cookie to cross-site POST/PATCH/PUT/DELETE). This
  // adds a second layer without requiring any frontend changes.
  if (
    isApiRoute &&
    request.method !== "GET" &&
    request.method !== "HEAD" &&
    request.method !== "OPTIONS"
  ) {
    const secFetchSite = request.headers.get("sec-fetch-site");
    if (
      secFetchSite &&
      secFetchSite !== "same-origin" &&
      secFetchSite !== "none"
    ) {
      return NextResponse.json(
        { success: false, error: { code: "FORBIDDEN", message: "Cross-origin request blocked" } },
        { status: 403 }
      );
    }

    const origin = request.headers.get("origin");
    if (origin && origin !== request.nextUrl.origin) {
      return NextResponse.json(
        { success: false, error: { code: "FORBIDDEN", message: "Cross-origin request blocked" } },
        { status: 403 }
      );
    }
  }

  if (isPublicPath || isPublicApiPath) {
    return NextResponse.next();
  }

  const token = request.cookies.get("auth_token")?.value;
  const refreshToken = request.cookies.get("refresh_token")?.value;

  const handleUnauthorized = () => {
    if (isApiRoute) {
      const response = NextResponse.json(
        { success: false, error: { code: "UNAUTHORIZED", message: "Unauthorized or Expired Token" } },
        { status: 401 }
      );
      response.cookies.delete("auth_token");
      response.cookies.delete("refresh_token");
      return response;
    } else {
      const loginUrl = new URL("/login", request.url);
      const response = NextResponse.redirect(loginUrl);
      response.cookies.delete("auth_token");
      response.cookies.delete("refresh_token");
      return response;
    }
  };

  const attemptRefresh = async () => {
    if (!refreshToken) return null;
    try {
      const ip = extractClientIp(request);
      const userAgent = request.headers.get("user-agent") || undefined;
      const data = await AuthService.refreshSession(refreshToken, { ip, userAgent });

      // Forward the refreshed token values to the downstream route so it can
      // authenticate against the new access token instead of attempting a
      // second refresh with the already-rotated refresh token. The full cookie
      // options are set on the response below for the browser.
      request.cookies.set("auth_token", data.token);
      request.cookies.set("refresh_token", data.refreshToken);

      const requestHeaders = new Headers(request.headers);
      requestHeaders.set("x-user-id", data.user.id);
      if (data.user.tenantId) {
        requestHeaders.set("x-tenant-id", data.user.tenantId);
      }
      if (data.user.role) {
        requestHeaders.set("x-role", data.user.role);
      }

      const response = NextResponse.next({
        request: {
          headers: requestHeaders,
        },
      });

      const commonCookieOptions = {
        httpOnly: true,
        secure: process.env.NODE_ENV === "production",
        sameSite: "lax" as const,
        path: "/",
      };

      response.cookies.set("auth_token", data.token, {
        ...commonCookieOptions,
        maxAge: 15 * 60,
      });

      const refreshOptions = {
        ...commonCookieOptions,
        maxAge: data.isExtendedSession ? 30 * 24 * 60 * 60 : undefined,
      };
      response.cookies.set("refresh_token", data.refreshToken, refreshOptions);

      return response;
    } catch (_err) {
      return null;
    }
  };

  if (!token) {
    const refreshResponse = await attemptRefresh();
    if (refreshResponse) {
      return refreshResponse;
    }
    return handleUnauthorized();
  }

  try {
    const payload = await verifyJWT(token);
    
    if (!payload) {
      const refreshResponse = await attemptRefresh();
      if (refreshResponse) {
        return refreshResponse;
      }
      return handleUnauthorized();
    }

    const requestHeaders = new Headers(request.headers);
    requestHeaders.set("x-user-id", payload.userId as string);
    
    if (payload.tenantId) {
      requestHeaders.set("x-tenant-id", payload.tenantId as string);
    }
    if (payload.roleId) {
      requestHeaders.set("x-role-id", payload.roleId as string);
    }
    if (payload.role) {
      requestHeaders.set("x-role", payload.role as string);
    }

    return NextResponse.next({
      request: {
        headers: requestHeaders,
      },
    });
   
  } catch (_error) {
    const refreshResponse = await attemptRefresh();
    if (refreshResponse) {
      return refreshResponse;
    }
    return handleUnauthorized();
  }
}

